"use strict";

var VERSION = {
  major : 2,
  minor : 15,
  patch : 0,
  label : "",
};

VERSION.string = VERSION.major + "." + VERSION.minor + "." + VERSION.patch;
if (VERSION.label) { VERSION.string = VERSION.string + "-" + VERSION.label; }

// ── Edition ───────────────────────────────────────────────────
// internal = the team build (shared token, reviewers, default libraries; never published).
// public   = Figma Community build, generated by tools/build-public.py: everything between
//            the @internal markers is removed and the @public block is switched on.
var EDITION         = "public";
var DEFAULT_DS_KEY  = null;
var DEFAULT_DS_NAME = null;
var CONFIG_SRC      = null;
var GUIDELINES_URL  = null;
var LLM_URL         = "";
var TELEMETRY       = null;
var API_BASE    = "https://api.figma.com/v1";
var LLM_API_KEY = ""; // Set by user in settings

// ── Storage Keys ───────────────────────────────────────────────
var STORAGE_KEYS = {
  figmaToken: "figma_token",
  llmApiKey: "llm_api_key",
  apiUrl: "llm_api_url",
  saveFigmaToken: "save_figma_token", // legacy (<= 2.0.1), cleaned up on save/clear
};

// ── Cached Tokens (loaded at runtime) ─────────────────────
var cachedLlamaApiKey = null;
var cachedApiUrl = null;

// ── Shared Figma token (2.6.0) ────────────────────────────────
// One read-only token from a dedicated Figma account, published in the guidelines gist:
//   "figmaToken": { "tokenB64": "<base64 of figd_…>", "expiresAt": "YYYY-MM-DD" }
// (plain "token" also works; base64 keeps secret scanners from revoking it in the gist).
// Users never enter a token. Reviewers are warned TOKEN_WARN_DAYS before it expires.
var TOKEN_WARN_DAYS = 10;
var sharedToken     = null;   // { token, expiresAt } | null
var tokenInvalid    = false;  // set when the API rejects it (401/403)

function b64decode(s) {
  var chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  s = String(s || "").replace(/[^A-Za-z0-9+\/]/g, "");
  var out = "", buf = 0, bits = 0;
  for (var i = 0; i < s.length; i++) {
    buf = ((buf << 6) | chars.indexOf(s.charAt(i))) & 0xFFFFFF;
    bits += 6;
    if (bits >= 8) { bits -= 8; out += String.fromCharCode((buf >> bits) & 255); }
  }
  return out;
}

function setSharedToken(guidelines) {
  sharedToken  = null;
  tokenInvalid = false;
  var t = guidelines && guidelines.figmaToken;
  if (!t) { return; }
  if (typeof t === "string") { t = { token: t }; }
  var tok = t.token ? String(t.token) : (t.tokenB64 ? b64decode(t.tokenB64) : "");
  tok = tok.replace(/^\s+|\s+$/g, "");
  if (tok.indexOf("figd_") !== 0) { return; }
  sharedToken = { token: tok, expiresAt: t.expiresAt ? String(t.expiresAt) : null };
}

function tokenStatus() {
  if (EDITION === "public") { return { state: "none" }; }   // public: no token at all
  if (!sharedToken) { return { state: "missing" }; }
  if (tokenInvalid) { return { state: "invalid", expiresAt: sharedToken.expiresAt }; }
  if (!sharedToken.expiresAt) { return { state: "ok", expiresAt: null }; }
  var exp = Date.parse(sharedToken.expiresAt.length === 10 ? sharedToken.expiresAt + "T23:59:59Z" : sharedToken.expiresAt);
  if (isNaN(exp)) { return { state: "ok", expiresAt: sharedToken.expiresAt }; }
  var now  = Date.now();
  var days = Math.max(0, Math.ceil((exp - now) / 86400000));
  var state = exp < now ? "expired" : (days <= TOKEN_WARN_DAYS ? "expiring" : "ok");
  return { state: state, daysLeft: days, expiresAt: sharedToken.expiresAt };
}

function sendTokenStatus() { send("TOKEN_STATUS", tokenStatus()); }

function showWelcomeOnce() {
  if (isDevMode()) { return; }
  figma.clientStorage.getAsync("welcome_seen").then(function(seen) {
    if (!seen) {
      send("FIRST_RUN", {});
      figma.clientStorage.setAsync("welcome_seen", true).catch(function() {});
    }
  }).catch(function() {});
}

// ── Node fetch helper for dynamic-page compatibility ─────
function getNodeSafely(id) {
  // Try sync first, fallback to async if it fails
  try {
    var node = figma.getNodeById(id);
    if (node) {
      return Promise.resolve(node);
    }
    // If sync returns null, try async
    return figma.getNodeByIdAsync(id);
  } catch(e) {
    // Sync failed (dynamic-page mode), use async
    return figma.getNodeByIdAsync(id);
  }
}

// ── Token Loader ──────────────────────────────────────────────
function loadTokens() {
  // Personal Figma tokens are no longer used (2.6.0): remove any left on this device.
  figma.clientStorage.deleteAsync(STORAGE_KEYS.figmaToken).catch(function() {});
  figma.clientStorage.deleteAsync(STORAGE_KEYS.saveFigmaToken).catch(function() {});
  return Promise.all([
    figma.clientStorage.getAsync(STORAGE_KEYS.llmApiKey),
    figma.clientStorage.getAsync(STORAGE_KEYS.apiUrl),
  ]).then(function(results) {
    cachedLlamaApiKey = results[0] || null;
    cachedApiUrl = results[1] || LLM_URL;
    return { hasLLM: !!cachedLlamaApiKey };
  });
}

// ── Boot ─────────────────────────────────────────────────────
// Opens at the default size, pinned to the top-left corner of the visible canvas.
// After that the user moves/resizes it freely (drag handle → RESIZE_FRAME, never below the minimum).
var UI_MIN_W     = 480;
var UI_MIN_H     = 520;
var UI_DEFAULT_W = 600;  // wide enough that most rows stay on one line
var UI_DEFAULT_H = 560;
var UI_MARGIN    = 8;    // screen px from the canvas edges

function topLeftPosition() {
  try {
    var b = figma.viewport.bounds;          // visible canvas area, canvas coordinates
    var z = figma.viewport.zoom || 1;       // screen px per canvas unit
    return { x: b.x + UI_MARGIN / z, y: b.y + UI_MARGIN / z };
  } catch (e) { return null; }
}

(function() {
  var opts = { width: UI_DEFAULT_W, height: UI_DEFAULT_H, title: "DAROOGHE", themeColors: true };   // themeColors: html gets figma-dark / figma-light
  var pos = topLeftPosition();
  if (pos) { opts.position = pos; }
  try { figma.showUI(__html__, opts); }
  catch (e) { figma.showUI(__html__, { width: UI_DEFAULT_W, height: UI_DEFAULT_H, title: "DAROOGHE", themeColors: true }); }
})();

// ── Selection Change ──────────────────────────────────────────
figma.on("selectionchange", function() {
  var selection = figma.currentPage.selection;
  if (!selection || selection.length === 0) { return; }
  var node = selection[0];
  send("SELECTION_CHANGED", { nodeId: node.id });
});
figma.on("selectionchange", function() { syncSelection(); scheduleVerifyCheck(150); });
figma.on("currentpagechange", function() { attachPageListener(); scheduleVerifyCheck(150); });
attachPageListener();

// ── Message Router ───────────────────────────────────────────
figma.ui.onmessage = function(msg) {
  if (msg.type === "INIT")             { handleInit();              }
  if (msg.type === "GET_FRAMES")       { handleGetFrames();         }
  if (msg.type === "RUN_AUDIT")        { handleRunAudit(msg);       }
  if (msg.type === "RUN_AI_ANALYSIS")  { handleAIAnalysis(msg);     }
  if (msg.type === "AI_FETCH_RESULT")  { handleAIFetchResult(msg);  }
  if (msg.type === "HIGHLIGHT_NODE")   { handleHighlightNode(msg);  }
  if (msg.type === "HIGHLIGHT_ALL")    { handleHighlightAll(msg);   }
  if (msg.type === "SAVE_LIBRARIES")   { handleSaveLibraries(msg);  }
  if (msg.type === "REGISTER_LIBRARY") { handleRegisterLibrary();   }
  if (msg.type === "SAVE_SETTINGS")    { handleSaveSettings(msg);   }
  if (msg.type === "FETCH_LIBRARY")    { handleFetchLibrary(msg);   }
  if (msg.type === "CHECK_VERIFICATION") { scheduleVerifyCheck(0);  }
  if (msg.type === "MARK_READY_FOR_DEV") { handleMarkReadyForDev(msg); }
  if (msg.type === "RESOLVE_ISSUE")    { handleResolveIssue(msg);   }
  if (msg.type === "RESOLVE_ISSUES")   { handleResolveIssues(msg);  }
  if (msg.type === "EXPORT_RESOLUTIONS") { handleExportResolutions(); }
  if (msg.type === "CANCEL_AUDIT")       { handleCancelAudit(); }
  if (msg.type === "SET_NO_WRITE")       { setNoWrite(msg.on, true); }
  if (msg.type === "SET_TELEMETRY")      { setTelemetryOff(!msg.on, true); }
  if (msg.type === "REPORT_WRONG")       { handleReportWrong(msg); }
  if (msg.type === "TM_LOG_GET")         { handleTmLog(); }
  if (msg.type === "TM_FLUSH_NOW")       { flushTelemetry().then(handleTmLog); }
  if (msg.type === "ESCALATE_PREPARE")   { handleEscalatePrepare(msg); }
  if (msg.type === "ESCALATE_SENT")      { handleEscalateSent(msg); }
    if (msg.type === "UNRESOLVE_ISSUE")  { handleUnresolveIssue(msg); }
  if (msg.type === "RESIZE_FRAME")     { handleResizeFrame(msg);    }
  if (msg.type === "CLOSE")            { figma.closePlugin();        }
};

// ── Handlers ─────────────────────────────────────────────────

function handleInit() {
  send("VERSION_INFO", { version: VERSION.string, label: VERSION.label });
  send("MODE_INFO", { editorType: figma.editorType });
  scheduleVerifyCheck(0);

  // Load guidelines (+ shared token) and libraries together
  Promise.all([
    fetchGuidelines(),
    figma.clientStorage.getAsync("custom_libraries"),
    loadTokens(),
  ]).then(function(results) {
    var guidelines = results[0];
    send("GUIDELINES_LOADED", { guidelines: guidelines });
    setReviewers(guidelines);
    setTeamRules(guidelines);
    setEscalation(guidelines);
    loadNoWrite();
    loadTelemetry().then(function() {
      track("open", { editor: figma.editorType, role: isAdmin() ? "admin" : isReviewer() ? "reviewer" : "designer", cfg: configSource });
      trackCoverage();
      scheduleTmFlush(TM_START_MS);   // whatever waited from earlier (e.g. audits outside the company network)
    });
        setSharedToken(guidelines);
    sendTokenStatus();
    if (EDITION === "public") {
      loadRegisteredLibraries().then(function(list) { send("LIBRARIES_LOADED", { libraries: libSummary(list) }); });
    } else {
      send("LIBRARIES_LOADED", { libraries: results[1] || [], teamLibraries: teamLibraries(guidelines) });
    }
  }).catch(function() {
    send("GUIDELINES_LOADED", { guidelines: null });
    setReviewers(null);
    setTeamRules(null);
    setEscalation(null);
    loadNoWrite();
    loadTelemetry();
    setSharedToken(null);
    sendTokenStatus();
    if (EDITION === "public") {
      loadRegisteredLibraries().then(function(list) { send("LIBRARIES_LOADED", { libraries: libSummary(list) }); });
    } else {
      figma.clientStorage.getAsync("custom_libraries").then(function(saved) {
        send("LIBRARIES_LOADED", { libraries: saved || [] });
      });
    }
  });
  showWelcomeOnce();

  syncSelection();
}
// Canvas selection → audit target(s). A selected section stays a section;
// anything else resolves to its top-level frame (parent is the page or a section).
function auditTargetFor(node) {
  if (!node) { return null; }
  if (node.type === "SECTION") { return node; }
  var cur = node;
  while (cur && cur.parent && cur.type !== "PAGE") {
    if (cur.parent.type === "PAGE" || cur.parent.type === "SECTION") {
      return isAuditTarget(cur) ? cur : null;
    }
    cur = cur.parent;
  }
  return null;
}

function syncSelection() {
  var selection = figma.currentPage.selection;
  if (!selection || selection.length === 0) { return; }
  var seen = {}, targets = [];
  for (var i = 0; i < selection.length; i++) {
    var t = auditTargetFor(selection[i]);
    if (t && !seen[t.id]) {
      seen[t.id] = true;
      targets.push({ id: t.id, name: t.name, type: t.type });
    }
  }
  if (!targets.length) { return; }
  send("CANVAS_FRAME_SELECTED", {
    id       : targets[0].id,
    name     : targets[0].name,
    nodeType : targets[0].type,   // not "type": send() uses that for the message type
    targets  : targets,
  });
}
// GitLab file API path for the config (project and file URL-encoded).
function cfgPath(suffix) {
  return CONFIG_SRC.host + "/api/v4/projects/" + encodeURIComponent(CONFIG_SRC.project) + "/repository/files/" + encodeURIComponent(CONFIG_SRC.file) + (suffix || "");
}
function cfgReadToken() { return CONFIG_SRC && CONFIG_SRC.readTokenB64 ? b64decode(CONFIG_SRC.readTokenB64).replace(/^\s+|\s+$/g, "") : ""; }
function fetchJson(url, headers) {
  return fetch(url, { headers: headers || {} }).then(function(res) {
    if (!res.ok) { throw new Error("HTTP " + res.status); }
    return res.json();
  });
}

function fetchGuidelines() {
  if (!CONFIG_SRC && !GUIDELINES_URL) { return Promise.resolve(null); }   // public edition: no team config
  var fromGitlab = function() {
    var tok = cfgReadToken();
    if (!tok) { return Promise.reject(new Error("no read token")); }
    return fetchJson(cfgPath("/raw?ref=" + encodeURIComponent(CONFIG_SRC.ref) + "&t=" + Date.now()), { "PRIVATE-TOKEN": tok });
  };
  // Cache-buster: GitHub's raw CDN (and Figma) can serve an old copy for minutes after a gist edit.
  var fromGist = function() { return GUIDELINES_URL ? fetchJson(GUIDELINES_URL + "?t=" + Date.now()) : Promise.reject(new Error("no gist")); };
  // GitLab first; outside the company network the copy saved here (it has the latest rules and settings),
  // and only when there is none yet the old gist — which must never overwrite a copy read from GitLab.
  var save = function(data) { figma.clientStorage.setAsync("cached_guidelines", data).catch(function() {}); return data; };
  return fromGitlab().then(function(data) { configSource = "gitlab"; return save(data); }, function() {
    return figma.clientStorage.getAsync("cached_guidelines").catch(function() { return null; }).then(function(cached) {
      if (cached) { configSource = "cache"; return cached; }
      return fromGist().then(function(data) { configSource = "gist"; return save(data); }, function() { configSource = "cache"; return null; });
    });
  });
}
var configSource = null;   // "gitlab" | "gist" | "cache" — where the current config came from

function handleGetFrames() {
  var frames   = [];
  var children = figma.currentPage.children;
  for (var i = 0; i < children.length; i++) {
    var node = children[i];
    if (
      node.type === "FRAME"         ||
      node.type === "COMPONENT"     ||
      node.type === "COMPONENT_SET" ||
      node.type === "SECTION"
    ) {
      frames.push({ id: node.id, name: node.name, type: node.type });
    }
  }
  send("FRAMES_LIST", { frames: frames });
}

function handleSaveLibraries(msg) {
  if (EDITION === "public") { savePublicLibraryFlags(msg.libraries || []); return; }
  figma.clientStorage.setAsync("custom_libraries", msg.libraries || []).catch(function() {});
}

// ── Registered libraries (public edition, no token) ───────────
// The user runs Darooghe once inside each design system library file; the plugin reads that
// file's components (keys + names) and keeps them in clientStorage, which is per user and works
// across all files. Audits then compare instance keys against this list — no REST API needed.
var REG_KEY = "registered_libraries";

function libSummary(list) {
  var out = [];
  for (var i = 0; i < (list || []).length; i++) {
    var l = list[i];
    out.push({ id: l.id, name: l.name, enabled: l.enabled !== false, count: l.count || 0, at: l.at || null });
  }
  return out;
}

function loadRegisteredLibraries() {
  return figma.clientStorage.getAsync(REG_KEY).then(function(list) { return Array.isArray(list) ? list : []; }, function() { return []; });
}

function savePublicLibraryFlags(flags) {
  loadRegisteredLibraries().then(function(list) {
    var byId = {};
    for (var i = 0; i < flags.length; i++) { byId[flags[i].id] = flags[i]; }
    var kept = [];
    for (var j = 0; j < list.length; j++) {
      var f = byId[list[j].id];
      if (!f) { continue; }                    // removed in the UI
      list[j].enabled = f.enabled !== false;
      kept.push(list[j]);
    }
    return figma.clientStorage.setAsync(REG_KEY, kept);
  }).catch(function() {});
}

function handleRegisterLibrary() {
  if (isDevMode()) { send("LIBRARY_REGISTERED", { success: false, code: "dev_mode" }); return; }
  var loadAll = figma.loadAllPagesAsync ? figma.loadAllPagesAsync() : Promise.resolve();
  loadAll.then(function() {
    var comps = [];
    try { comps = figma.root.findAllWithCriteria({ types: ["COMPONENT"] }); } catch(e) { comps = []; }
    // Only what designers can actually use: published components. Changes not published yet don't count
    // ("CHANGED" = published, with edits waiting — the key and the published version are what instances use).
    return Promise.all(comps.map(function(c) {
      var p;
      try { p = c.getPublishStatusAsync ? c.getPublishStatusAsync() : "CURRENT"; } catch(e) { p = "CURRENT"; }
      return Promise.resolve(p).then(function(st) { return st; }, function() { return "CURRENT"; });
    })).then(function(states) {
    var map = {}, count = 0;
    for (var i = 0; i < comps.length; i++) {
      if (states[i] === "UNPUBLISHED") { continue; }
      var key = null;
      try { key = comps[i].key; } catch(e) {}
      if (!key) { continue; }
      map[key] = componentNames(comps[i]).name || comps[i].name;
      count++;
    }
    if (!count) { send("LIBRARY_REGISTERED", { success: false, code: "no_components" }); return null; }
    var name = figma.root.name || "Untitled library";
    var id = "file:" + name;
    return loadRegisteredLibraries().then(function(list) {
      var entry = { id: id, name: name, enabled: true, count: count, at: new Date().toISOString(), comps: map };
      var replaced = false;
      for (var j = 0; j < list.length; j++) { if (list[j].id === id) { list[j] = entry; replaced = true; } }
      if (!replaced) { list.push(entry); }
      return figma.clientStorage.setAsync(REG_KEY, list).then(function() {
        send("LIBRARY_REGISTERED", { success: true, name: name, count: count, updated: replaced, libraries: libSummary(list) });
      });
    });
    });
  }).catch(function(err) {
    send("LIBRARY_REGISTERED", { success: false, error: err.message });
  });
}

// Same shape fetchDSComponents() resolves to: [[{ key, name, sourceName }]]
function registeredComponents() {
  return loadRegisteredLibraries().then(function(list) {
    var out = [];
    for (var i = 0; i < list.length; i++) {
      if (list[i].enabled === false) { continue; }
      var comps = list[i].comps || {}, arr = [];
      for (var k in comps) { arr.push({ key: k, name: comps[k], sourceName: list[i].name }); }
      out.push(arr);
    }
    return out;
  });
}

function handleResizeFrame(msg) {
  try {
    var width = Number(msg.width) || 760;
    var height = Number(msg.height) || 620;
    figma.ui.resize(Math.max(UI_MIN_W, width), Math.max(UI_MIN_H, height));
  } catch (e) {}
}

function handleSaveSettings(msg) {
  // Only the (hidden) AI settings remain; the Figma token is shared via the guidelines gist.
  var promises = [];
  if (msg.llmApiKey) { promises.push(figma.clientStorage.setAsync(STORAGE_KEYS.llmApiKey, msg.llmApiKey)); }
  if (msg.apiUrl)    { promises.push(figma.clientStorage.setAsync(STORAGE_KEYS.apiUrl, msg.apiUrl)); }
  Promise.all(promises).then(function() {
    if (msg.llmApiKey) { cachedLlamaApiKey = msg.llmApiKey; }
    if (msg.apiUrl)    { cachedApiUrl = msg.apiUrl; }
    send("SETTINGS_SAVED", { success: true, hasLLM: !!cachedLlamaApiKey });
  }).catch(function(err) {
    send("SETTINGS_SAVED", { success: false, error: err.message });
  });
}

// Team libraries for everyone, managed by admins in the guidelines gist:
//   "libraries": [ { "key": "<file key>", "name": "…" } ]
function teamLibraries(guidelines) {
  var out = [];
  var list = guidelines && guidelines.libraries;
  if (!list || !list.length) { return out; }
  for (var i = 0; i < list.length; i++) {
    var l = list[i];
    if (l && typeof l.key === "string" && /^[A-Za-z0-9]+$/.test(l.key)) {
      out.push({ key: l.key, name: String(l.name || l.key).slice(0, 120) });
    }
  }
  return out;
}

// Settings → Add library (admins only): read the file name with the shared token (the token never reaches the UI).
function handleFetchLibrary(msg) {
  if (EDITION !== "public" && !isAdmin()) {
    send("LIBRARY_INFO", { success: false, fileKey: msg.fileKey, code: "not_admin" });
    return;
  }
  var ts = tokenStatus();
  if (ts.state === "missing" || ts.state === "expired" || ts.state === "invalid") {
    send("LIBRARY_INFO", { success: false, fileKey: msg.fileKey, code: ts.state });
    return;
  }
  fetch(API_BASE + "/files/" + msg.fileKey + "?depth=1", { headers: { "X-Figma-Token": sharedToken.token } })
    .then(function(res) {
      if (res.status === 401 || res.status === 403 || res.status === 404) {
        return fetch(API_BASE + "/me", { headers: { "X-Figma-Token": sharedToken.token } }).then(function(me) {
          if (me.ok) { send("LIBRARY_INFO", { success: false, fileKey: msg.fileKey, code: "no_access" }); }
          else { tokenInvalid = true; sendTokenStatus(); send("LIBRARY_INFO", { success: false, fileKey: msg.fileKey, code: "invalid" }); }
          return null;
        });
      }
      if (!res.ok) { throw new Error("HTTP " + res.status); }
      return res.json().then(function(data) {
        send("LIBRARY_INFO", { success: true, fileKey: msg.fileKey, name: data.name || msg.fileKey });
      });
    })
    .catch(function(err) { send("LIBRARY_INFO", { success: false, fileKey: msg.fileKey, error: err.message }); });
}

// Selected nodes → the top-level nodes to audit. Sections (also nested ones) expand to their contents;
// hidden ones are skipped. Duplicates and targets inside another target are dropped, so nothing counts twice.
function isAuditTarget(node) {
  return isFrameLike(node) || (!!node && (node.type === "GROUP" || node.type === "INSTANCE"));
}

function expandTargets(nodes) {
  var out = [];
  function add(n) {
    if (!n || n.visible === false) { return; }
    if (n.type === "SECTION") {
      for (var i = 0; i < n.children.length; i++) { add(n.children[i]); }
    } else if (isAuditTarget(n)) { out.push(n); }
  }
  for (var j = 0; j < nodes.length; j++) { add(nodes[j]); }
  var ids = {};
  for (var k = 0; k < out.length; k++) { ids[out[k].id] = true; }
  var seen = {}, res = [];
  for (var m = 0; m < out.length; m++) {
    var node = out[m];
    if (seen[node.id]) { continue; }
    var p = node.parent, inside = false;
    while (p && p.type !== "PAGE") { if (ids[p.id]) { inside = true; break; } p = p.parent; }
    if (inside) { continue; }
    seen[node.id] = true;
    res.push(node);
  }
  return res;
}

var AUDIT_CONCURRENCY = 16;   // instances analysed at the same time
var MAIN_RETRY_MS     = [400, 900, 1600];   // waits before asking again for a main component that came back empty

// Runs worker(item) for every item, at most `limit` at once. Never rejects.
function runPool(items, limit, worker, onProgress) {
  return new Promise(function(resolve) {
    var next = 0, active = 0, done = 0;
    if (!items.length) { resolve(); return; }
    function launch() {
      while (active < limit && next < items.length) {
        var item = items[next++];
        active++;
        var p;
        try { p = Promise.resolve(worker(item)); } catch(e) { p = Promise.resolve(); }
        p.then(settle, settle);
      }
    }
    function settle() {
      active--; done++;
      if (onProgress) { try { onProgress(done, items.length); } catch(e) {} }
      if (done === items.length) { resolve(); } else { launch(); }
    }
    launch();
  });
}

// Cancelling: every audit gets a run number; CANCEL_AUDIT (or a newer audit) moves it on, and each stage of an
// older run stops where it is — no result, no verification or history written.
var auditRun = 0;
function handleCancelAudit() {
  track("cancel", {});
  auditRun++;
  mainMemo = null;
  send("AUDIT_CANCELLED", {});
}

function handleRunAudit(msg) {
  var myRun = ++auditRun, t0 = Date.now();
  var cancelled = function() { return myRun !== auditRun; };
  sendStatus("Fetching Design System components...", "st_fetch");

  var figmaToken = null;
  var notes = [];          // things the user should know about this result (e.g. an offline DS list)
  var libsPromise;
  var activeLibs = [];
  if (EDITION === "public") {
    // Public: components come from libraries the user registered (no token, no network).
    libsPromise = registeredComponents().then(function(results) {
      var n = 0;
      for (var q = 0; q < results.length; q++) { n += results[q].length; }
      if (!n) { var e = new Error("no_libraries"); e.code = "no_libraries"; throw e; }
      return results;
    });
  } else {
    var ts = tokenStatus();
    if (ts.state === "missing" || ts.state === "expired" || ts.state === "invalid") {
      sendTokenStatus();
      send("ERROR", { text: "", code: "token_" + ts.state });
      return;
    }
    figmaToken = sharedToken.token;

    activeLibs = msg.activeLibs && msg.activeLibs.length > 0
      ? msg.activeLibs
      : [{ key: DEFAULT_DS_KEY, name: DEFAULT_DS_NAME }];

    var fetchPromises = [];
    for (var k = 0; k < activeLibs.length; k++) {
      fetchPromises.push(fetchDSComponents(activeLibs[k].key, activeLibs[k].name, figmaToken, notes));
    }
    libsPromise = Promise.all(fetchPromises);
  }

  // Library file keys that count as the design system (for classifying remote components).
  var dsFileNames = {};
  for (var dl = 0; dl < activeLibs.length; dl++) { dsFileNames[activeLibs[dl].key] = activeLibs[dl].name; }

  libsPromise.then(function(results) {
    if (cancelled()) { return; }
    var dsKeys        = {};
    var dsNames       = {};
    var dsSourceNames = {};
    var dsSets        = {};   // variant key → component set name
    var totalCount    = 0;

    for (var r = 0; r < results.length; r++) {
      var components = results[r];
      for (var c = 0; c < components.length; c++) {
        dsKeys[components[c].key]        = true;
        dsNames[components[c].key]       = components[c].name;
        dsSourceNames[components[c].key] = components[c].sourceName;
        if (components[c].set) { dsSets[components[c].key] = components[c].set; }
        totalCount++;
      }
    }

    sendStatus(totalCount + " DS components loaded — scanning...", "st_loaded", { n: totalCount });

    // Use safe node fetching for each frame
    var frameIdsToFetch = (msg.frameIds && msg.frameIds.length > 0) ? msg.frameIds : [msg.frameId];
    var nodePromises = frameIdsToFetch.map(function(id) {
      return getNodeSafely(id);
    });

    return Promise.all(nodePromises).then(function(targetFrames) {
      var validFrames = targetFrames.filter(function(n) { return n !== null; });
      if (!validFrames.length) { send("ERROR", { text: "Frame not found.", code: "frame_not_found" }); return; }

      var finalFrames = expandTargets(validFrames);

      if (!finalFrames.length) { send("ERROR", { text: "No frames found to audit.", code: "no_frames" }); return; }

      var allInstances = [];
      var allDetached  = [];
      var rawWarnings  = [];   // layers outside components with raw (untokenised) styles — warnings, not issues
      var frameInstanceCounts = [];
      var instanceFrameIndex = {};
      rawSeen = 0; rawHit = 0;
      var skippedEmpty = 0;    // several targets: frames without components are labels / notes, not screens
      for (var ff = 0; ff < finalFrames.length; ff++) {
        var frameList = [], frameDetached = [];
        collectInstances(finalFrames[ff], frameList, frameDetached);
        // A detached frame is an issue only when it was a design-system component (it no longer gets DS updates).
        // Detached from anything else it is just a frame — its contents are still checked like any frame.
        frameDetached = frameDetached.filter(function(fr) { var info = safeGet(fr, "detachedInfo") || {}; return !!(info.componentKey && dsKeys[info.componentKey]); });
        var rawFrom = rawWarnings.length;
        if (finalFrames.length > 1 && !frameList.length && !frameDetached.length) { skippedEmpty++; }
        else { collectRaw(finalFrames[ff], rawWarnings); }
        for (var rw = rawFrom; rw < rawWarnings.length; rw++) { rawWarnings[rw].frameId = finalFrames[ff].id; rawWarnings[rw].frameName = finalFrames[ff].name; }
        frameInstanceCounts.push(frameList.length + frameDetached.length);
        for (var fl = 0; fl < frameList.length; fl++) {
          instanceFrameIndex[frameList[fl].id] = ff;
          allInstances.push(frameList[fl]);
        }
        for (var fd = 0; fd < frameDetached.length; fd++) {
          instanceFrameIndex[frameDetached[fd].id] = ff;
          allDetached.push(frameDetached[fd]);
        }
      }

      if (rawWarnings.length >= RAW_MAX) { notes.push({ code: "raw_more", n: RAW_MAX }); }
      if (skippedEmpty) { notes.push({ code: "empty_skipped", n: skippedEmpty }); }
      if (cancelled()) { return; }
      sendStatus(allInstances.length + " instances found — analyzing...", "st_found", { n: allInstances.length });

      var valid   = [];
      var invalid = [];
      var deferred = [];        // remote components not in the DS list: looked up together after the scan
      var unverified = 0;       // of those, how many the API couldn't confirm
      var pendingMain = [];     // no main component yet: asked again before they count as MIS
      var order    = {};
      for (var oi = 0; oi < allInstances.length; oi++) { order[allInstances[oi].id] = oi; }
      for (var od = 0; od < allDetached.length; od++) { order[allDetached[od].id] = allInstances.length + od; }
      // Detached from a library component: an issue (DET), named after the component when it's in the DS list.
      // A reviewer may have accepted it as an exception (checked with the other issues below).
      var detachedChecks = allDetached.map(function(fr) {
        return function() { return finishIssue(fr, buildDetachedItem(fr, dsNames, dsSets), null); };
      });

      // All lookups in parallel (cached per key), then classify each instance like the main pass.
      function resolveDeferred() {
        if (cancelled()) { return Promise.resolve(); }
        sendStatus("Checking " + deferred.length + " component(s) from other files…", "st_remote", { n: deferred.length });
        return Promise.all(deferred.map(function(d) {
          return lookupRemoteComponent(d.main.key, dsFileNames).then(function(info) {
            if (info.state === "found" && dsFileNames[info.fileKey] !== undefined) {
              return finishDS(d.instance, d.main, d.overrides, componentNames(d.main).name, dsFileNames[info.fileKey]);
            }
            var issue = buildInvalidItem(d.instance, info.state === "missing" ? "outdated" : "external_library", d.main, d.overrides);
            if (info.fileName && info.state === "found") { issue.source = info.fileName; if (isArchivedLibrary(info.fileName)) { issue.archived = true; } }
            if (info.state === "unknown") { issue.unverified = true; unverified++; }   // API didn't answer: EXT is a guess
            return finishIssue(d.instance, issue, null);
          }).catch(function() {
            var issue = buildInvalidItem(d.instance, "external_library", d.main, d.overrides);
            issue.unverified = true; unverified++;
            invalid.push(issue);
          });
        })).then(function() {
          if (unverified) { notes.push({ code: "lookup_failed", n: unverified }); }
        });
      }

      // A DS component: nested parts swapped to non-DS components count as overrides too.
      function finishDS(instance, main, overrides, dsName, source) {
        return findBadSwaps(instance, dsKeys, dsFileNames).then(function(swaps) {
          var all = overrides.concat(swaps);
          if (!all.length) { valid.push(buildValidItem(instance, dsName, source)); return; }
          return finishIssue(instance, buildInvalidItem(instance, "ds_overridden", main, all), source || null);
        });
      }

      function finishIssue(instance, issue, sourceName) {
        var esc = readEscalation(instance);
        if (esc) { issue.escalated = esc; }             // already sent to the DS team
        // A team rule (gist) accepts this exact pattern everywhere — no per-instance exception needed.
        var rule = matchTeamRule(issue);
        if (rule) { valid.push(buildRuleItem(instance, issue, rule, sourceName)); return Promise.resolve(); }
        return checkResolution(instance, issue).then(function(res) {
          if (res.state === "resolved") { valid.push(buildResolvedItem(instance, issue, res.record, sourceName)); }
          else {
            if (res.state === "stale") { issue.staleResolution = publicResolution(res.record); }
            invalid.push(issue);
          }
        }, function() { invalid.push(issue); });
      }

      // Each instance: main component → class → issue (+ resolution). Runs AUDIT_CONCURRENCY at a time;
      // results are put back in layer order at the end, so the list doesn't depend on timing.
      function classify(instance) {
        if (cancelled()) { return; }
        return getMain(instance).then(function(main) {
          if (!main) { pendingMain.push(instance); return; }   // retried below before it counts as MIS

          var overrides = detectOverrides(instance);

          // Where does this component really come from? Remote keys not in the DS list are looked up
          // (team build): another library → EXT with its file name; a DS file → DS after all;
          // no longer published (old/deleted version) → OLD.
          var cls;
          if (isUnpublishedComponent(main))  { cls = { reason: "unpublished" }; }
          else if (dsKeys[main.key])          { cls = { ds: true, source: dsSourceNames[main.key], dsName: dsNames[main.key] }; }
          else if (!main.remote)              { cls = { reason: "local_component" }; }
          else if (EDITION !== "public")      { deferred.push({ instance: instance, main: main, overrides: overrides }); return; }
          else                                { cls = { reason: "external_library" }; }

          if (cls.ds) { return finishDS(instance, main, overrides, cls.dsName, cls.source); }
          var issue = buildInvalidItem(instance, cls.reason, main, overrides);
          if (cls.source) { issue.source = cls.source; }
          // A DS reviewer may have approved this exact deviation (see Resolutions).
          return finishIssue(instance, issue, null);
        }).catch(function() {
          return finishIssue(instance, buildInvalidItem(instance, "missing_main", null, []), null);
        });
      }

      var lastProgress = 0;
      function progress(done, total) {
        if (cancelled()) { return; }
        var now = Date.now();
        if (done < total && now - lastProgress < 250) { return; }
        lastProgress = now;
        sendStatus("Analyzing " + done + " / " + total + " instances…", "st_progress", { n: done, total: total });
      }

      function byLayerOrder(a, b) { return order[a.id] - order[b.id]; }

      function finish() {
        if (cancelled()) { return; }          // stopped: nothing sent, nothing written
        valid.sort(byLayerOrder);
        invalid.sort(byLayerOrder);
        // Which audited frame each result belongs to (the UI can group by frame when several were audited).
        var tagFrame = function(it) { var fi = instanceFrameIndex[it.id]; if (fi !== undefined) { it.frameId = finalFrames[fi].id; it.frameName = finalFrames[fi].name; } };
        valid.forEach(tagFrame); invalid.forEach(tagFrame);
        auditedFrames = {};
        for (var af = 0; af < finalFrames.length; af++) { auditedFrames[finalFrames[af].id] = true; }
        lastAuditOverrides = {};
        for (var lo = 0; lo < invalid.length; lo++) { lastAuditOverrides[invalid[lo].id] = invalid[lo].overrides || []; }
        var auditName = finalFrames.length === 1
          ? finalFrames[0].name
          : finalFrames.length + " frames";
        var frameIssueCounts = [];
        for (var fi = 0; fi < finalFrames.length; fi++) { frameIssueCounts.push(0); }
        for (var ii = 0; ii < invalid.length; ii++) {
          var idx = instanceFrameIndex[invalid[ii].id];
          if (idx !== undefined) { frameIssueCounts[idx]++; }
        }

        var frameResolvedCounts = [];
        for (var fr = 0; fr < finalFrames.length; fr++) { frameResolvedCounts.push(0); }
        for (var vr = 0; vr < valid.length; vr++) {
          if (!valid[vr].resolved) { continue; }
          var vIdx = instanceFrameIndex[valid[vr].id];
          if (vIdx !== undefined) { frameResolvedCounts[vIdx]++; }
        }

        var libKeys = [];
        for (var lk = 0; lk < activeLibs.length; lk++) { libKeys.push(activeLibs[lk].key); }

        var sendResult = function(frameStates) {
          trackAudit(t0, valid, invalid, rawWarnings, frameStates, notes);
          send("AUDIT_RESULT", {
            pluginVersion    : VERSION.string,
            noWrite          : noWrite,       // measured without writing to the file
            frameId          : msg.frameId || (msg.frameIds && msg.frameIds[0]),
            frameName        : auditName,
            totalInstances   : allInstances.length + allDetached.length,
            validCount       : valid.length,
            invalidCount     : invalid.length,
            validInstances   : valid,
            invalidInstances : invalid,
            warnings         : rawWarnings,
            frames           : frameStates,
            notes            : notes,
            fileKey          : currentFileKey(),
            fileName         : figma.root ? figma.root.name : "",
            auditTimestamp   : new Date().toISOString(),
          });
          scheduleVerifyCheck(0);
        };

        finalizeVerification(finalFrames, frameInstanceCounts, frameIssueCounts, libKeys, frameResolvedCounts)
          .then(function(st) { if (cancelled()) { return; } mainMemo = null; sendResult(st); })
          .catch(function() { mainMemo = null; sendResult([]); });
      }

      // Right after a file opens, Figma can answer "no main component" while library components are still
      // loading. Those instances are asked again a few times (gently) before they count as MIS.
      function retryPendingMain(round) {
        if (!pendingMain.length || cancelled()) { return Promise.resolve(); }
        if (round >= MAIN_RETRY_MS.length) {
          // Still no main component: MIS — checked against accepted exceptions like every other issue.
          var missing = pendingMain;
          pendingMain = [];
          return Promise.all(missing.map(function(inst) { return finishIssue(inst, buildInvalidItem(inst, "missing_main", null, []), null); }));
        }
        var batch = pendingMain;
        pendingMain = [];
        return new Promise(function(r) { setTimeout(r, MAIN_RETRY_MS[round]); })
          .then(function() { return runPool(batch, 4, classify); })
          .then(function() { return retryPendingMain(round + 1); });
      }

      mainMemo = {};
      runPool(allInstances, AUDIT_CONCURRENCY, classify, progress)
        .then(function() { return runPool(detachedChecks, AUDIT_CONCURRENCY, function(f) { return f(); }); })
        .then(function() { return retryPendingMain(0); })
        .then(function() { return deferred.length ? resolveDeferred() : null; })
        .then(finish, finish);

    });

  }).catch(function(err) {
    if (cancelled()) { return; }
    if (err && err.code === "no_libraries") { send("ERROR", { text: "", code: "no_libraries" }); return; }
    if (err && (err.status === 401 || err.status === 403)) {
      // Bad token, or the bot account can't open this library file. /me tells them apart.
      fetch(API_BASE + "/me", { headers: { "X-Figma-Token": figmaToken } }).then(function(res) {
        if (res.ok) { send("ERROR", { text: "", code: "lib_no_access", lib: err.fileName || "" }); return; }
        tokenInvalid = true;
        sendTokenStatus();
        send("ERROR", { text: "", code: "token_invalid" });
      }).catch(function() { send("ERROR", { text: "Failed to fetch DS: " + err.message, code: "ds_fetch" }); });
      return;
    }
    send("ERROR", { text: "Failed to fetch DS: " + err.message, code: "ds_fetch" });
  });
}

// ── AI Analysis ───────────────────────────────────────────────

function handleAIAnalysis(msg) {
  sendStatus("Analyzing with AI...");
  // Use cached tokens
  var apiUrl = cachedApiUrl || LLM_URL;
  var apiKey = cachedLlamaApiKey || LLM_API_KEY;
  if (!apiKey) {
    send("AI_ANALYSIS_ERROR", { error: "LLM API key not set. Please configure in settings." });
    return;
  }
  // ← API call رو اینجا می‌زنیم مستقیم!
  makeAICall(apiUrl, apiKey, buildPrompt(msg.auditData, msg.guidelines));
}

function makeAICall(apiUrl, apiKey, prompt) {
  // Remove trailing slash from apiUrl if present
  var baseUrl = apiUrl.replace(/\/$/, "");
  var fullUrl = baseUrl + "/chat/completions";
  fetch(fullUrl, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": "Bearer " + apiKey,
    },
    body: JSON.stringify({
      model: "claude-3.5-sonnet",
      messages: [{ role: "user", content: prompt }],
      temperature: 0.2,
      stream: false,
    }),
  }).then(function(res) {
    if (!res.ok) { throw new Error("HTTP " + res.status); }
    return res.json();
  }).then(function(data) {
    var content = data.choices[0].message.content;
    handleAIFetchResult({ content: content });
  }).catch(function(err) {
    handleAIFetchResult({ error: err.message });
  });
}
function handleAIFetchResult(msg) {
  if (msg.error) {
    send("AI_ANALYSIS_ERROR", { error: msg.error });
    return;
  }
  try {
    var raw   = msg.content;
    var clean = raw.replace(/^```json\s*/i, "").replace(/```\s*$/i, "").trim();
    var result = JSON.parse(clean);
    send("AI_ANALYSIS_RESULT", { analysis: result });
  } catch(e) {
    send("AI_ANALYSIS_ERROR", { error: "JSON parse error: " + e.message });
  }
}
function buildPrompt(auditData, guidelines) {
  // فقط invalid instances رو میفرستیم — توکن کمتر
  var simplifiedInvalid = [];
  for (var i = 0; i < auditData.invalidInstances.length; i++) {
    var inst = auditData.invalidInstances[i];
    simplifiedInvalid.push({
      id       : inst.id,
      name     : inst.name,
      reason   : inst.reason,
      overrides: inst.overrides,
      parent   : inst.parent ? inst.parent.name : null,
      path     : inst.path,
    });
  }

  var lines = [
    "You are a senior Design System expert reviewing a Figma design.",
    "Your job is to analyze audit results and provide actionable feedback in Persian (فارسی).",
    "",
    "## Design System Guidelines (JSON):",
    JSON.stringify(guidelines, null, 2),
    "",
    "## Audit Summary:",
    "- Frame: " + auditData.frameName,
    "- Total instances: " + auditData.totalInstances,
    "- Valid (from DS): " + auditData.validCount,
    "- Invalid (outside DS): " + auditData.invalidCount,
    "",
    "## Invalid Instances:",
    JSON.stringify(simplifiedInvalid, null, 2),
    "",
    "## Instructions:",
    "1. Analyze each invalid instance against the guidelines",
    "2. Write all text fields in Persian (فارسی)",
    "3. Be specific and actionable",
    "4. Reference guideline IDs when applicable",
    "",
    "## Response — strict JSON, no extra text:",
    JSON.stringify({
      summary: "خلاصه کلی ارزیابی در ۱-۲ جمله",
      score: 85,
      issues: [
        {
          instanceId   : "node-id",
          instanceName : "نام کامپوننت",
          severity     : "critical",
          reason       : "دلیل مشکل",
          suggestion   : "راه حل پیشنهادی",
          guidelineRef : "guideline id یا topic مرتبط"
        }
      ],
      recommendations: [
        "توصیه کلی اول",
        "توصیه کلی دوم"
      ]
    }, null, 2),
  ];

  return lines.join("\n");
}

// ── Highlight ─────────────────────────────────────────────────

// Calm canvas navigation (2.10.0):
//  · already on screen at a readable size → select only, the view doesn't move
//  · off screen → glide there at the current zoom
//  · zoom changes only when needed: zoom out if it doesn't fit, zoom in if it would be tiny
//  · a small layer inside a component is framed with its component (contextId) for orientation
//  · the camera glides in ~200 ms; msg.instant (reduced motion) jumps
var FOCUS_MIN_PX   = 24;    // smaller than this on screen → zoom in
var FOCUS_TARGET_PX = 160;  // …until its longest side is about this big
var FOCUS_FILL     = 0.8;   // never let the target take more than 80% of the view
var FOCUS_MAX_ZOOM = 8;
var FOCUS_STEPS    = 10;
var FOCUS_STEP_MS  = 20;
var focusSeq = 0;

function boxOf(nodes) {
  var x1 = Infinity, y1 = Infinity, x2 = -Infinity, y2 = -Infinity;
  for (var i = 0; i < nodes.length; i++) {
    var b = null;
    try { b = nodes[i].absoluteRenderBounds || nodes[i].absoluteBoundingBox; } catch(e) { b = null; }
    if (!b) { continue; }
    x1 = Math.min(x1, b.x); y1 = Math.min(y1, b.y); x2 = Math.max(x2, b.x + b.width); y2 = Math.max(y2, b.y + b.height);
  }
  return x1 === Infinity ? null : { x: x1, y: y1, width: Math.max(1, x2 - x1), height: Math.max(1, y2 - y1) };
}

function pageOf(node) {
  var p = node;
  while (p && p.type !== "PAGE") { p = p.parent; }
  return p;
}

function glideTo(center, zoom, instant) {
  var seq = ++focusSeq;
  var vp = figma.viewport;
  var c0 = vp.center, z0 = vp.zoom;
  if (instant || (Math.abs(c0.x - center.x) * z0 < 1 && Math.abs(c0.y - center.y) * z0 < 1 && Math.abs(z0 - zoom) < 0.001)) {
    vp.zoom = zoom; vp.center = center; return;
  }
  var i = 0;
  (function step() {
    if (seq !== focusSeq) { return; }                     // a newer click took over
    i++;
    var t = i / FOCUS_STEPS;
    var e = 1 - Math.pow(1 - t, 3);                        // ease-out
    var z = z0 * Math.pow(zoom / z0, e);                   // zoom interpolates geometrically (feels linear)
    try {
      vp.zoom = z;
      vp.center = { x: c0.x + (center.x - c0.x) * e, y: c0.y + (center.y - c0.y) * e };
    } catch(err) { return; }
    if (i < FOCUS_STEPS) { setTimeout(step, FOCUS_STEP_MS); }
  })();
}

function focusOn(selectNodes, frameNodes, instant) {
  var box = boxOf(frameNodes);
  figma.currentPage.selection = selectNodes;
  if (!box) { try { figma.viewport.scrollAndZoomIntoView(selectNodes); } catch(e) {} return; }
  var vb = figma.viewport.bounds, z = figma.viewport.zoom;
  var screenW = vb.width * z, screenH = vb.height * z;
  var fitZoom = Math.min(screenW * FOCUS_FILL / box.width, screenH * FOCUS_FILL / box.height);
  var longest = Math.max(box.width, box.height) * z;
  var zoom = z;
  if (z > fitZoom) { zoom = fitZoom; }                                                   // too big: zoom out to fit
  else if (longest < FOCUS_MIN_PX) {                                                    // too small: zoom in
    zoom = Math.min(FOCUS_TARGET_PX / Math.max(box.width, box.height), fitZoom, Math.max(z, FOCUS_MAX_ZOOM));
  }
  var inside = box.x >= vb.x && box.y >= vb.y && box.x + box.width <= vb.x + vb.width && box.y + box.height <= vb.y + vb.height;
  if (inside && zoom === z) { return; }                                                 // visible and readable: don't move
  glideTo({ x: box.x + box.width / 2, y: box.y + box.height / 2 }, zoom, instant);
}

function handleHighlightNode(msg) {
  Promise.all([getNodeSafely(msg.nodeId), msg.contextId ? getNodeSafely(msg.contextId) : Promise.resolve(null)]).then(function(r) {
    var node = r[0], ctx = r[1];
    if (!node || node.removed) { return; }
    var page = pageOf(node);
    var ready = (page && page !== figma.currentPage) ? figma.setCurrentPageAsync(page) : Promise.resolve();
    return ready.then(function() {
      // Frame the component around a small layer, unless the layer itself is already large.
      var frameWith = [node];
      if (ctx && !ctx.removed && ctx !== node) {
        var b = boxOf([node]);
        if (!b || Math.max(b.width, b.height) * figma.viewport.zoom < FOCUS_TARGET_PX) { frameWith = [ctx]; }
      }
      focusOn([node], frameWith, !!msg.instant);
    });
  }).catch(function() {});
}

function handleHighlightAll(msg) {
  var nodePromises = msg.nodeIds.map(function(id) {
    return getNodeSafely(id);
  });
  Promise.all(nodePromises).then(function(nodes) {
    var validNodes = nodes.filter(function(n) { return n && !n.removed && pageOf(n) === figma.currentPage; });
    if (!validNodes.length) { return; }
    focusOn(validNodes, validNodes, !!msg.instant);
  }).catch(function() {});
}

// ── Fetch DS Components ───────────────────────────────────────

// DS component lists are cached: in memory for DS_CACHE_MS (repeat audits skip the slow /components call),
// and the last good list in clientStorage as a fallback when the API can't be reached. A component published
// after the cached list still classifies correctly: unknown remote keys go through lookupRemoteComponent().
var DS_CACHE_MS     = 10 * 60 * 1000;
var DS_CACHE_PREFIX = "ds_cache_";
var dsMemCache      = {};   // fileKey → { at, list: [{ key, name }] }

function withSource(list, fileName) {
  var out = [];
  for (var i = 0; i < list.length; i++) { out.push({ key: list[i].key, name: list[i].name, set: list[i].set || null, sourceName: fileName }); }
  return out;
}

function fetchDSComponents(fileKey, fileName, token, notes) {
  if (!token) {
    return Promise.reject(new Error("Figma token not set. Please enter it in the session settings."));
  }
  var mem = dsMemCache[fileKey];
  if (mem && Date.now() - mem.at < DS_CACHE_MS) { return Promise.resolve(withSource(mem.list, fileName)); }

  return fetch(API_BASE + "/files/" + fileKey + "/components", {
    headers: { "X-Figma-Token": token },
  }).then(function(res) {
    if (res.status === 401 || res.status === 403) {
      // 403 is also what Figma returns when the bot account can't see this file
      var err = new Error("HTTP " + res.status + " for file " + fileKey);
      err.status = res.status; err.fileName = fileName;
      throw err;
    }
    if (!res.ok) { throw new Error("HTTP " + res.status + " for file " + fileKey); }
    return res.json();
  }).then(function(data) {
    var src  = (data.meta && data.meta.components) ? data.meta.components : [];
    var list = [];
    for (var i = 0; i < src.length; i++) {
      var cf  = src[i].containing_frame;
      var set = cf && cf.containingComponentSet ? cf.containingComponentSet.name : null;
      list.push(set ? { key: src[i].key, name: src[i].name, set: set } : { key: src[i].key, name: src[i].name });
    }
    var at = Date.now();
    dsMemCache[fileKey] = { at: at, list: list };
    figma.clientStorage.setAsync(DS_CACHE_PREFIX + fileKey, { at: at, list: list }).catch(function() {});
    return withSource(list, fileName);
  }).catch(function(err) {
    if (err && err.status) { throw err; }    // auth / access: the caller explains it
    // Network trouble: fall back to the last list we saw for this library.
    return figma.clientStorage.getAsync(DS_CACHE_PREFIX + fileKey).then(function(saved) {
      if (!saved || !saved.list) { throw err; }
      if (notes) { notes.push({ code: "ds_cached", lib: fileName, at: new Date(saved.at).toISOString() }); }
      return withSource(saved.list, fileName);
    }, function() { throw err; });
  });
}

// ── Override Detection ────────────────────────────────────────

// Each issue: { type, field, node, value } — "value" is the current value in readable form,
// so the UI can say exactly what changed (e.g. "Fill Color #FF0000").
function detectOverrides(instance) {
  var issues = [];
  try {
    var overrides = instance.overrides;
    if (!overrides || overrides.length === 0) { return issues; }

    var index = {};
    indexSubtree(instance, index);

    for (var i = 0; i < overrides.length; i++) {
      var ov      = overrides[i];
      var changed = ov.overriddenFields;
      if (!changed || changed.length === 0) { continue; }

      var node     = index[ov.id] || null;
      if (node && hiddenInInstance(node, instance)) { continue; }   // not rendered, so it can't deviate
      var nodeName = node ? node.name : ov.id;
      var has = function(f) { return changed.indexOf(f) > -1; };
      var nodeId   = node ? node.id : null;
      var add = function(type, field, value) {
        issues.push({ type: type, field: field, node: nodeName, nodeId: nodeId, value: value || "" });
      };

      // Values that come from a variable or a style are tokens, not overrides.
      var typoTokenised = node && hasStyle(node, "textStyleId");
      var typo = function(fieldName, label, value, varField) {
        if (!has(fieldName) || typoTokenised || (node && hasBoundVariable(node, varField || fieldName))) { return; }
        add("typography", label, value());
      };
      typo("fontName",       "Font Family",     function() { return node ? fmtFontName(safeGet(node, "fontName")) : ""; }, "fontFamily");
      typo("fontSize",       "Font Size",       function() { return node ? fmtNumber(safeGet(node, "fontSize")) : ""; });
      typo("fontWeight",     "Font Weight",     function() { return node ? fmtNumber(safeGet(node, "fontWeight")) : ""; });
      typo("letterSpacing",  "Letter Spacing",  function() { return node ? fmtUnitValue(safeGet(node, "letterSpacing")) : ""; });
      typo("lineHeight",     "Line Height",     function() { return node ? fmtUnitValue(safeGet(node, "lineHeight")) : ""; });
      typo("textCase",       "Text Case",       function() { return node ? fmtPlain(safeGet(node, "textCase")) : ""; });
      typo("textDecoration", "Text Decoration", function() { return node ? fmtPlain(safeGet(node, "textDecoration")) : ""; });

      var fillDev = (has("fills") && node && !hasStyle(node, "fillStyleId")) ? paintDeviation(safeGet(node, "fills")) : null;
      if (fillDev !== null) { add("color", "Fill Color", fillDev); }
      var strokeDev = (has("strokes") && node && !hasStyle(node, "strokeStyleId")) ? paintDeviation(safeGet(node, "strokes")) : null;
      if (strokeDev !== null) { add("stroke", "Stroke Color", strokeDev); }
      if (has("strokeWeight") && !(node && hasBoundVariable(node, "strokeWeight")) && !allBound(node, STROKE_WEIGHT_VARS)) { add("stroke", "Stroke Weight", node ? fmtNumber(safeGet(node, "strokeWeight"), "px") : ""); }
      if (has("opacity") && node && !hasBoundVariable(node, "opacity")) {
        var op = safeGet(node, "opacity");
        add("color", "Opacity", typeof op === "number" ? Math.round(op * 100) + "%" : "");
      }
      var pads = changedOf(changed, PADDING_FIELDS);
      if (pads.length && !allBound(node, pads)) {
        add("spacing", "Padding", node ? fmtPadding(node) : "");
      }
      if (has("itemSpacing") && !allBound(node, ["itemSpacing"])) { add("spacing", "Gap / Item Spacing", node ? fmtNumber(safeGet(node, "itemSpacing"), "px") : ""); }
      // Size: only a manual resize counts. Hug/Fill, auto-sizing text, stretch/scale constraints and the
      // instance itself (resizing a component is normal use) follow content or layout, not a hard-coded size.
      if (node && ((has("width") && sizeIsFixed(node, instance, "h") && !hasBoundVariable(node, "width")) ||
                   (has("height") && sizeIsFixed(node, instance, "v") && !hasBoundVariable(node, "height")))) {
        add("size", "Dimensions", fmtNumber(safeGet(node, "width")) + "×" + fmtNumber(safeGet(node, "height")));
      }
      var radii = changedOf(changed, RADIUS_FIELDS);
      if (radii.length && !allBound(node, has("cornerRadius") ? RADIUS_FIELDS.slice(1) : radii)) {
        add("style", "Corner Radius", node ? fmtRadius(node) : "");
      }
      if (has("effects") && !(node && (hasStyle(node, "effectStyleId") || hasBoundVariable(node, "effects")))) {
        var fx = node ? safeGet(node, "effects") : null;
        add("style", "Effects / Shadow", node ? fmtEffects(fx) : "");
        issues[issues.length - 1].sv = Array.isArray(fx) ? fx.length + "" : "";   // value as signed before 2.11 (exceptions)
      }
    }
  } catch(e) {}

  return issues;
}

// The layer (or a parent inside this instance) is hidden.
function hiddenInInstance(node, instance) {
  var cur = node;
  while (cur && cur !== instance && cur.id !== instance.id) {
    if (safeGet(cur, "visible") === false) { return true; }
    cur = cur.parent;
  }
  return false;
}

var PADDING_FIELDS     = ["paddingLeft", "paddingRight", "paddingTop", "paddingBottom"];
var RADIUS_FIELDS      = ["cornerRadius", "topLeftRadius", "topRightRadius", "bottomLeftRadius", "bottomRightRadius"];
var STROKE_WEIGHT_VARS = ["strokeTopWeight", "strokeRightWeight", "strokeBottomWeight", "strokeLeftWeight"];

function changedOf(changed, list) {
  var out = [];
  for (var i = 0; i < list.length; i++) { if (changed.indexOf(list[i]) > -1) { out.push(list[i]); } }
  return out;
}

// Every listed field bound to a variable (number variables for spacing, radius, stroke weight).
function allBound(node, list) {
  if (!node || !list.length) { return false; }
  for (var i = 0; i < list.length; i++) { if (!hasBoundVariable(node, list[i])) { return false; } }
  return true;
}

// A (non-mixed) style is applied, e.g. a library color or text style.
function hasStyle(node, key) {
  var id = safeGet(node, key);
  return typeof id === "string" && id !== "";
}

// ── Raw styles outside components (RAW, warnings) ─────────────
// Layers that aren't inside an instance: a visible fill/stroke without a variable or style, and text without
// a text style. Spacing, radius and effects aren't checked (not tokenised in every team). Images and
// invisible paints are fine.
// Warnings only: they show in the results but don't count as issues or block verification.
var RAW_MAX = 300;   // per audit

function rawPaint(paints) {
  if (!Array.isArray(paints)) { return null; }
  for (var i = 0; i < paints.length; i++) {
    var p = paints[i];
    if (!p || p.visible === false) { continue; }
    if (p.type === "SOLID" && !(p.boundVariables && p.boundVariables.color)) { return fmtPaint(p); }
    if (String(p.type).indexOf("GRADIENT") === 0) {
      var stops = p.gradientStops || [];
      for (var k = 0; k < stops.length; k++) {
        if (!(stops[k].boundVariables && stops[k].boundVariables.color)) { return "Gradient"; }
      }
    }
  }
  return null;
}

function textStyled(node) {
  var id = safeGet(node, "textStyleId");
  if (typeof id === "string") { return id !== ""; }
  if (id === figma.mixed) {
    try {
      var segs = node.getStyledTextSegments(["textStyleId"]);
      for (var i = 0; i < segs.length; i++) { if (!segs[i].textStyleId) { return false; } }
    } catch(e) {}
  }
  return true;
}

function rawProblems(node) {
  var out = [];
  var add = function(type, field, value) { out.push({ type: type, field: field, node: node.name, nodeId: node.id, value: value || "" }); };
  if (!hasStyle(node, "fillStyleId")) {
    var fp = rawPaint(safeGet(node, "fills"));
    if (fp) { add("color", "Fill Color", fp); }
  }
  var sw = safeGet(node, "strokeWeight");
  if (!hasStyle(node, "strokeStyleId") && (sw === figma.mixed || sw > 0)) {
    var sp = rawPaint(safeGet(node, "strokes"));
    if (sp) { add("stroke", "Stroke Color", sp); }
  }
  if (node.type === "TEXT" && !textStyled(node)) { add("typography", "Text Style", ""); }
  return out;
}

// A library whose file name says it is archived / deprecated (e.g. "DS (Archive- 18 Mordad 04)").
var ARCHIVED_LIB_RE = /archive|archived|deprecated|legacy|آرشیو|منسوخ/i;
function isArchivedLibrary(name) { return !!name && ARCHIVED_LIB_RE.test(name); }

// Shapes drawn by hand inside a group (badges, illustrations): artwork, not UI — no raw-colour warnings.
var VECTOR_ART = { VECTOR: true, BOOLEAN_OPERATION: true, STAR: true, POLYGON: true, LINE: true, ELLIPSE: true };

// Layers checked for raw values / layers with one (usage statistics: the real share of tokens), counted past RAW_MAX.
var rawSeen = 0, rawHit = 0, RAW_COUNT_MAX = 20000;
function collectRaw(node, out, inGroup) {
  if (!node || node.visible === false) { return; }
  if (out.length >= RAW_MAX && rawSeen >= RAW_COUNT_MAX) { return; }   // enough warnings and enough counted
  if (node.type === "INSTANCE") { return; }                    // components are checked by the audit itself
  if (inGroup && VECTOR_ART[node.type]) { return; }
  if (node.type !== "GROUP" && node.type !== "SECTION" && node.type !== "SLICE") {
    var probs = rawProblems(node);
    rawSeen++;
    if (probs.length) { rawHit++; }
    if (probs.length && out.length < RAW_MAX) {
      out.push({ id: node.id, name: node.name, nodeType: node.type, problems: probs, path: getNodePath(node), parent: getDirectParent(node) });
    }
  }
  if (node.type === "BOOLEAN_OPERATION") { return; }           // its parts are drawn with the operation's paint
  var grp = node.type === "GROUP" ? true : (isFrameLike(node) ? false : !!inGroup);   // a frame inside a group is UI again
  if (node.children) {
    for (var i = 0; i < node.children.length; i++) { collectRaw(node.children[i], out, grp); }
  }
}

// ── Nested swaps ──────────────────────────────────────────────
// A nested instance inside a DS component that now points to a different component than in the
// component's definition was swapped. It's an issue when the new component isn't from the DS:
// local (LOC), another library (EXT) or no longer published (OLD). Internal "_" parts are fine.
// The definition's layer is the last part of the nested ID ("I1:2;3:4" → "3:4").
function definitionNodeId(id) {
  var parts = String(id || "").split(";");
  return parts.length > 1 ? parts[parts.length - 1] : null;
}

function mainKeyOf(node) { return getMain(node); }

// Main component of an instance; null when it can't be resolved. During an audit the result is memoised,
// so the fingerprint and snapshot use exactly what the audit saw (and don't ask Figma again).
var mainMemo = null;   // instance id → main component (only while an audit runs)
function getMain(node) {
  if (mainMemo && mainMemo[node.id]) { return Promise.resolve(mainMemo[node.id]); }
  var p;
  try { p = node.getMainComponentAsync(); } catch(e) { return Promise.resolve(null); }
  return Promise.resolve(p).then(function(m) {
    if (m && mainMemo) { mainMemo[node.id] = m; }
    return m || null;
  }, function() { return null; });
}

function findBadSwaps(instance, dsKeys, dsFileNames) {
  var ovs = [];
  try { ovs = instance.overrides || []; } catch(e) { ovs = []; }
  var targets = [], seen = {};
  for (var i = 0; i < ovs.length; i++) {
    if (seen[ovs[i].id] || ovs[i].id === instance.id) { continue; }
    seen[ovs[i].id] = true;
    if (definitionNodeId(ovs[i].id)) { targets.push(ovs[i].id); }
  }
  if (!targets.length) { return Promise.resolve([]); }
  var index = {};
  indexSubtree(instance, index);
  return Promise.all(targets.map(function(id) {
    var node = index[id];
    if (!node || node.type !== "INSTANCE" || hiddenInInstance(node, instance)) { return null; }
    return Promise.all([mainKeyOf(node), getNodeSafely(definitionNodeId(id)).then(function(n) {
      return n && n.type === "INSTANCE" ? mainKeyOf(n) : null;
    }, function() { return null; })]).then(function(r) {
      var now = r[0], orig = r[1];
      if (!now || !orig || now.key === orig.key) { return null; }      // not a swap (or can't tell)
      if (dsKeys[now.key] || isUnpublishedComponent(now)) { return null; }
      var swapIssue = function(code) {
        return { type: "swap", field: "Swapped Component", node: node.name, nodeId: node.id, value: componentNames(now).name + " (" + code + ")" };
      };
      if (!now.remote) { return swapIssue("LOC"); }
      return lookupRemoteComponent(now.key, dsFileNames).then(function(info) {
        if (info.state === "found" && dsFileNames[info.fileKey] !== undefined) { return null; }
        return swapIssue(info.state === "missing" ? "OLD" : "EXT");
      }, function() { return swapIssue("EXT"); });
    }, function() { return null; });
  })).then(function(list) {
    var out = [];
    for (var j = 0; j < list.length; j++) { if (list[j]) { out.push(list[j]); } }
    return out;
  }, function() { return []; });
}

// Is this axis of a layer inside an instance a fixed, hand-set size?
function sizeIsFixed(node, instance, axis) {
  if (!node || node.id === instance.id) { return false; }
  var sizing = safeGet(node, axis === "h" ? "layoutSizingHorizontal" : "layoutSizingVertical");
  if (sizing && sizing !== "FIXED") { return false; }                      // HUG / FILL
  if (node.type === "TEXT") {
    var ar = safeGet(node, "textAutoResize");
    if (ar === "WIDTH_AND_HEIGHT") { return false; }
    if (ar === "HEIGHT" && axis === "v") { return false; }
  }
  var c = safeGet(node, "constraints");
  var k = c ? (axis === "h" ? c.horizontal : c.vertical) : null;
  if (k === "STRETCH" || k === "SCALE") { return false; }                  // follows its parent's size
  return true;
}

// ── Value Formatting ──────────────────────────────────────────

function safeGet(node, key) {
  try { return node[key]; } catch(e) { return undefined; }
}

function fmtNumber(v, unit) {
  if (v === figma.mixed) { return "mixed"; }
  if (typeof v !== "number") { return ""; }
  return (Math.round(v * 100) / 100) + (unit || "");
}

function fmtPlain(v) {
  if (v === figma.mixed) { return "mixed"; }
  return (v === undefined || v === null) ? "" : String(v);
}

function fmtFontName(v) {
  if (v === figma.mixed) { return "mixed"; }
  return (v && v.family) ? v.family + " " + v.style : "";
}

function fmtUnitValue(v) {
  if (v === figma.mixed) { return "mixed"; }
  if (!v || typeof v !== "object") { return ""; }
  if (v.unit === "AUTO") { return "Auto"; }
  if (v.unit === "PERCENT") { return (Math.round(v.value * 100) / 100) + "%"; }
  return (Math.round(v.value * 100) / 100) + "px";
}

function fmtPadding(node) {
  var t = fmtNumber(safeGet(node, "paddingTop")),  r = fmtNumber(safeGet(node, "paddingRight"));
  var b = fmtNumber(safeGet(node, "paddingBottom")), l = fmtNumber(safeGet(node, "paddingLeft"));
  if (t === r && r === b && b === l) { return t + "px"; }
  return t + " " + r + " " + b + " " + l;
}

function fmtRadius(node) {
  var cr = safeGet(node, "cornerRadius");
  if (cr !== figma.mixed) { return fmtNumber(cr, "px"); }
  return [fmtNumber(safeGet(node, "topLeftRadius")), fmtNumber(safeGet(node, "topRightRadius")),
          fmtNumber(safeGet(node, "bottomRightRadius")), fmtNumber(safeGet(node, "bottomLeftRadius"))].join(" ");
}

function toHex(c) {
  function h(v) { var x = Math.round(v * 255).toString(16); return x.length < 2 ? "0" + x : x; }
  return ("#" + h(c.r) + h(c.g) + h(c.b)).toUpperCase();
}

function firstHardcodedPaint(paints) {
  if (!Array.isArray(paints)) { return null; }
  for (var i = 0; i < paints.length; i++) {
    var p = paints[i];
    if (p.type !== "SOLID" || p.visible === false) { continue; }
    if (p.boundVariables && p.boundVariables.color) { continue; }
    return p;
  }
  return null;
}

// An overridden paint list that isn't tokenised: a raw solid color (its hex), a gradient whose stops
// aren't all variables ("Gradient"), or every paint removed/hidden ("None"). Image/video fills are content.
// null = fine.
function paintDeviation(paints) {
  if (!Array.isArray(paints)) { return null; }      // mixed / unreadable
  var visible = [];
  for (var i = 0; i < paints.length; i++) { if (paints[i] && paints[i].visible !== false) { visible.push(paints[i]); } }
  if (!visible.length) { return "None"; }
  var solid = firstHardcodedPaint(visible);
  if (solid) { return fmtPaint(solid); }
  for (var j = 0; j < visible.length; j++) {
    var p = visible[j];
    if (String(p.type).indexOf("GRADIENT") !== 0) { continue; }
    var stops = p.gradientStops || [];
    for (var k = 0; k < stops.length; k++) {
      if (!(stops[k].boundVariables && stops[k].boundVariables.color)) { return "Gradient"; }
    }
  }
  return null;
}

function fmtEffects(fx) {
  if (fx === figma.mixed) { return "mixed"; }
  if (!Array.isArray(fx)) { return ""; }
  var vis = [];
  for (var i = 0; i < fx.length; i++) { if (fx[i] && fx[i].visible !== false) { vis.push(fx[i]); } }
  if (!vis.length) { return "None"; }
  var e = vis[0], out;
  if (e.type === "DROP_SHADOW" || e.type === "INNER_SHADOW") {
    var o = e.offset || { x: 0, y: 0 };
    var c = e.color ? toHex(e.color) + (e.color.a !== undefined && e.color.a < 1 ? " " + Math.round(e.color.a * 100) + "%" : "") : "";
    out = (e.type === "DROP_SHADOW" ? "Drop shadow " : "Inner shadow ") + fmtNumber(o.x) + " " + fmtNumber(o.y) + " " + fmtNumber(e.radius) + (c ? " " + c : "");
  } else {
    out = (e.type === "BACKGROUND_BLUR" ? "Background blur " : "Blur ") + fmtNumber(e.radius);
  }
  return vis.length > 1 ? out + " +" + (vis.length - 1) : out;
}

function fmtPaint(p) {
  if (!p || !p.color) { return ""; }
  var o = (p.opacity === undefined) ? 1 : p.opacity;
  return toHex(p.color) + (o < 1 ? " " + Math.round(o * 100) + "%" : "");
}

// ── Color Helpers ─────────────────────────────────────────────

function hasBoundVariable(node, field) {
  try {
    var bound = node.boundVariables;
    if (!bound) { return false; }
    return !!bound[field];
  } catch(e) { return false; }
}

// ── Unpublished Check ─────────────────────────────────────────
// Variants: the publish-hiding "_" lives on the COMPONENT_SET name, not the variant.
function isUnpublishedComponent(main) {
  try {
    var name = (main.parent && main.parent.type === "COMPONENT_SET") ? main.parent.name : main.name;
    return !!(name && name.charAt(0) === "_");
  } catch(e) { return false; }
}

// ── Verification (handoff) ────────────────────────────────────
// A frame that passes the audit with zero issues gets a record in shared plugin data,
// including a fingerprint of everything the audit checks. If the fingerprint no longer
// matches, the frame changed after verification. Text content and geometry are excluded
// on purpose: copy edits and resizing do not invalidate a verification.

var VERIFY_NS  = "darooghe";
var VERIFY_KEY = "verification";
var FP_VERSION = 2; // bump when the fingerprint algorithm changes; older stamps become "outdated"

var FP_SKIP_OVERRIDE_FIELDS = {
  characters: true, width: true, height: true, x: true, y: true,
  name: true, relativeTransform: true, textAutoResize: true,
};

var FP_NODE_PROPS = [
  "fills", "strokes", "strokeWeight", "strokeAlign", "effects", "opacity", "blendMode",
  "fillStyleId", "strokeStyleId", "effectStyleId", "textStyleId",
  "fontName", "fontSize", "fontWeight", "letterSpacing", "lineHeight", "textCase", "textDecoration",
  "cornerRadius", "topLeftRadius", "topRightRadius", "bottomLeftRadius", "bottomRightRadius",
  "layoutMode", "itemSpacing", "paddingLeft", "paddingRight", "paddingTop", "paddingBottom",
  "boundVariables",
];

function isDevMode() { return figma.editorType === "dev"; }

function isFrameLike(node) {
  return !!node && (node.type === "FRAME" || node.type === "COMPONENT" || node.type === "COMPONENT_SET");
}

function fpValue(v) {
  if (v === figma.mixed) { return "~mixed"; }
  if (v === undefined || v === null) { return ""; }
  try { return JSON.stringify(v); } catch(e) { return "?"; }
}

function fpNodeProps(node) {
  var out = [];
  for (var i = 0; i < FP_NODE_PROPS.length; i++) {
    var key = FP_NODE_PROPS[i];
    try {
      if (key in node) {
        var val = node[key];
        if (key === "boundVariables" && val) {
          // Variable bindings on width/height/characters are geometry/text — skip them.
          var filtered = {};
          for (var bk in val) {
            if (!FP_SKIP_OVERRIDE_FIELDS[bk]) { filtered[bk] = val[bk]; }
          }
          val = filtered;
        }
        out.push(key + "=" + fpValue(val));
      }
    } catch(e) {}
  }
  return out.join(";");
}

function indexSubtree(node, map) {
  map[node.id] = node;
  if ("children" in node) {
    for (var i = 0; i < node.children.length; i++) { indexSubtree(node.children[i], map); }
  }
}

function fpOverrideValue(target, field) {
  try { if (field in target) { return fpValue(target[field]); } } catch(e) {}
  return "?";
}

// Instance fingerprint: component key, non-text properties, and every override
// with its CURRENT VALUE (not just the field name). Layers that are not overridden
// are left out, so accepting a library update does not invalidate a verification.
function fpInstance(node) {
  return getMain(node).then(function(main) {
    var parts = ["key=" + (main ? main.key : "none")];

    try {
      var props = node.componentProperties || {};
      var names = [];
      for (var pn in props) { names.push(pn); }
      names.sort();
      for (var i = 0; i < names.length; i++) {
        var prop = props[names[i]];
        if (prop && prop.type !== "TEXT") { parts.push("p:" + names[i] + "=" + fpValue(prop.value)); }
      }
    } catch(e) {}

    var ovs = [];
    try { ovs = node.overrides || []; } catch(e) {}

    var index   = null;
    var entries = [];
    var swaps   = [];
    for (var j = 0; j < ovs.length; j++) {
      var fields = [];
      var src = ovs[j].overriddenFields || [];
      for (var k = 0; k < src.length; k++) {
        if (!FP_SKIP_OVERRIDE_FIELDS[src[k]]) { fields.push(src[k]); }
      }
      if (!fields.length) { continue; }
      fields.sort();
      if (!index) { index = {}; indexSubtree(node, index); }
      var target = index[ovs[j].id] || null;
      var vals = [];
      for (var f = 0; f < fields.length; f++) {
        vals.push(fields[f] + "=" + (target ? fpOverrideValue(target, fields[f]) : "?"));
      }
      var entry = { id: ovs[j].id, text: ovs[j].id + ":" + vals.join(",") };
      entries.push(entry);
      if (target && target !== node && target.type === "INSTANCE") { swaps.push({ entry: entry, target: target }); }
    }

    // Nested instance overrides (e.g. icon swaps): record which component it points to now.
    var lookups = [];
    for (var s = 0; s < swaps.length; s++) {
      lookups.push(getMain(swaps[s].target).then(function(mc) { return mc ? mc.key : "none"; }));
    }
    return Promise.all(lookups).then(function(keys) {
      for (var q = 0; q < swaps.length; q++) { swaps[q].entry.text += ",main=" + keys[q]; }
      entries.sort(function(x, y) { return x.id < y.id ? -1 : (x.id > y.id ? 1 : 0); });
      var texts = [];
      for (var e = 0; e < entries.length; e++) { texts.push(entries[e].text); }
      parts.push("ov=" + texts.join("|"));
      return parts.join(";");
    });
  });
}

function fpWalk(node, depth, parts, instances) {
  var head = depth + ":" + node.type + (node.visible === false ? "!hidden" : "");
  if (node.type === "INSTANCE") {
    instances.push({ node: node, index: parts.length, head: head });
    parts.push(head);
    return;
  }
  parts.push(head + "|" + fpNodeProps(node));
  if ("children" in node) {
    for (var i = 0; i < node.children.length; i++) {
      fpWalk(node.children[i], depth + 1, parts, instances);
    }
  }
}

function fnvMul(h) {
  // h * 16777619 mod 2^32 without Math.imul (ES5).
  return (h + (h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24)) >>> 0;
}

function fpHash(str) {
  // Two FNV-1a passes with different seeds → 64 bits, plenty for change detection.
  var h1 = 0x811c9dc5, h2 = 0x01000193;
  for (var i = 0; i < str.length; i++) {
    var c = str.charCodeAt(i);
    h1 ^= c; h1 = fnvMul(h1);
    h2 ^= (c + 0x9e37) & 0xffff; h2 = fnvMul(h2);
  }
  return ("0000000" + h1.toString(16)).slice(-8) + ("0000000" + h2.toString(16)).slice(-8);
}

function computeFingerprint(frame) {
  var parts = [];
  var instances = [];
  fpWalk(frame, 0, parts, instances);
  var lookups = [];
  for (var i = 0; i < instances.length; i++) {
    lookups.push(fpInstance(instances[i].node).then(null, function() { return "?"; }));
  }
  return Promise.all(lookups).then(function(texts) {
    for (var j = 0; j < instances.length; j++) {
      parts[instances[j].index] = instances[j].head + "|" + texts[j];
    }
    return fpHash(parts.join("\n"));
  });
}

function readVerification(node) {
  try {
    var raw = node.getSharedPluginData(VERIFY_NS, VERIFY_KEY);
    if (!raw) { return null; }
    var rec = JSON.parse(raw);
    return (rec && rec.fp) ? rec : null;
  } catch(e) { return null; }
}

// ── Audit without writing (measuring old files, e.g. the baseline) ──
// While on, audits and the automatic history write nothing to the file: no verification, history, snapshots or
// record upgrades. Deliberate actions (accept an exception, Mark ready) still work. Saved per computer.
// Admins only (team build): a designer who forgot it on would lose their verification stamps. Not in the public build.
var noWrite = false;
var NO_WRITE_KEY = "no_write";
function canNoWrite() { return EDITION !== "public" && isAdmin(); }
function setNoWrite(on, persist) {
  noWrite = !!on && canNoWrite();
  if (persist) { figma.clientStorage.setAsync(NO_WRITE_KEY, noWrite).catch(function() {}); }
  send("NO_WRITE", { on: noWrite });
}
// ── Usage statistics (team build) ────────────────────────────
// So the DS team can see adoption and compliance over time. Counts and codes only — no layer, frame or file
// names, no text, no images; the user and the file are hashed. Events queue on this computer (TM_QUEUE_KEY,
// max TM_MAX) and go to GitLab in batches when it is reachable (company network / VPN); outside it they wait.
// Nothing happens in the public build (TELEMETRY = null) or when switched off in Settings › Team.
var TM_QUEUE_KEY = "tm_queue", TM_OFF_KEY = "tm_off", TM_MAX = 1000, TM_BATCH = 200, TM_FLUSH_MS = 20000, TM_START_MS = 5000;
var tmOff = false, tmFlushing = false, tmTimer = null, tmChain = Promise.resolve();
var TM_SID = Math.random().toString(36).slice(2, 10);   // one plugin run: groups the events of a session
// Admins can see the last events and the last upload in Settings › Admin (checking that tracking works).
var TM_RECENT_MAX = 25, tmRecent = [], tmLastUpload = null;   // { at, status, n }
var tmHcSeen = {};   // handoff changes already reported in this run (frame + fingerprint)
function tmOn() { return !!TELEMETRY && !tmOff; }
function tmHash(str) { return str ? fpHash("darooghe/" + str).slice(0, 12) : null; }
function tmQueue(edit) {   // read → change → write, one at a time
  tmChain = tmChain.then(function() {
    return figma.clientStorage.getAsync(TM_QUEUE_KEY).then(function(q) {
      var next = edit(q || []);
      if (next.length > TM_MAX) { next = next.slice(next.length - TM_MAX); }
      return figma.clientStorage.setAsync(TM_QUEUE_KEY, next);
    });
  }).catch(function() {});
  return tmChain;
}
function track(event, data) {
  if (!tmOn()) { return; }
  var ev = { e: event, ts: new Date().toISOString(), v: VERSION.string, u: tmHash(me().id), f: tmHash(currentFileKey()), sid: TM_SID };
  for (var k in (data || {})) { ev[k] = data[k]; }
  tmRecent.push({ e: event, ts: ev.ts, keys: Object.keys(ev).filter(function(x) { return ev[x] !== null && ev[x] !== undefined; }), sent: false });
  if (tmRecent.length > TM_RECENT_MAX) { tmRecent = tmRecent.slice(-TM_RECENT_MAX); }
  tmQueue(function(q) { return q.concat([ev]); });
  scheduleTmFlush(TM_FLUSH_MS);
}
function scheduleTmFlush(ms) {
  if (tmTimer) { clearTimeout(tmTimer); }
  tmTimer = setTimeout(function() { tmTimer = null; flushTelemetry(); }, ms);
}
function setTelemetryOff(off, persist) {
  tmOff = !!off;
  if (persist) { figma.clientStorage.setAsync(TM_OFF_KEY, tmOff).catch(function() {}); }
  if (tmOff) { tmQueue(function() { return []; }); }   // off = nothing more leaves this computer
  send("TELEMETRY_INFO", { available: !!TELEMETRY, on: tmOn() });
}
function handleTmLog() {
  if (!isAdmin()) { return; }
  tmChain.then(function() { return figma.clientStorage.getAsync(TM_QUEUE_KEY); }).then(function(q) {
    send("TM_LOG", { on: tmOn(), items: tmRecent.slice().reverse(), queued: (q || []).length, last: tmLastUpload, hasToken: !!(TELEMETRY && TELEMETRY.tokenB64) });
  }, function() {});
}
function loadTelemetry() {
  return figma.clientStorage.getAsync(TM_OFF_KEY).then(function(v) { setTelemetryOff(!!v, false); }, function() {});
}
function flushTelemetry() {
  if (!tmOn() || tmFlushing) { return Promise.resolve(); }
    return Promise.resolve();
}
// The audited frame a node belongs to, hashed like the audit's frames (fr[].h) so events can be joined.
function tmFrame(node) { var top = node ? (topFrameOf(node) || node) : null; return top ? tmHash(currentFileKey() + ":" + top.id) : null; }
function tmFramesOf(ids) {
  return Promise.all((ids || []).slice(0, 50).map(function(id) { return getNodeSafely(id).then(tmFrame, function() { return null; }); })).then(function(hs) {
    var out = [];
    hs.forEach(function(h) { if (h && out.indexOf(h) < 0) { out.push(h); } });
    return out;
  });
}
// «This issue is wrong»: how precise the checker is (issue code, component, which kinds of override).
function handleReportWrong(msg) {
  var code = { missing_main: "MIS", detached: "DET", external_library: "EXT", outdated: "OLD", local_component: "LOC", unpublished: "UNP", ds_overridden: "MOD" };
  tmFramesOf([msg.nodeId]).then(function(fh) {
    track("wrong", { r: code[msg.reason] || msg.reason || null, c: String(msg.component || "").slice(0, 80), ov: (msg.fields || []).slice(0, 10), fh: fh });
    send("WRONG_RESULT", { nodeId: msg.nodeId, ok: tmOn() });
  });
}
// Ready-for-dev frames on the page and how many carry a Darooghe stamp — how much of the handoff is checked.
function trackCoverage() {
  if (!tmOn() || isDevMode()) { return; }
  var ready = 0, stamped = 0, frames = 0;
  var look = function(n) {
    if (n.type === "SECTION") { (n.children || []).forEach(look); return; }
    if (!isAuditTarget(n)) { return; }
    frames++;
    if (readDevStatus(n) === "READY_FOR_DEV") { ready++; if (readVerification(n)) { stamped++; } }
  };
  try { (figma.currentPage.children || []).forEach(look); } catch(e) { return; }
  if (ready) { track("cover", { pg: tmHash(currentFileKey() + ":" + figma.currentPage.id), frames: frames, ready: ready, stamped: stamped }); }
}
// One audit, as numbers: what was checked, how it went, and which components cause the issues.
function trackAudit(t0, valid, invalid, warnings, frameStates, notes) {
  if (!tmOn()) { return; }
  var code = { missing_main: "MIS", detached: "DET", external_library: "EXT", outdated: "OLD", local_component: "LOC", unpublished: "UNP", ds_overridden: "MOD" };
  var r = {}, mod = {}, w = {}, comps = {}, acc = 0, rule = 0, ver = 0, fail = 0, empty = 0;
  invalid.forEach(function(it) {
    var c = code[it.reason] || it.reason;
    r[c] = (r[c] || 0) + 1;
    (it.overrides || []).forEach(function(o) { mod[o.type] = (mod[o.type] || 0) + 1; });
    var ck = c + "|" + (it.componentName || it.mainComponentName || "");
    comps[ck] = (comps[ck] || 0) + 1;
  });
  valid.forEach(function(it) { if (it.resolved) { if (it.resolved.rule) { rule++; } else { acc++; } } });
  (warnings || []).forEach(function(x) { (x.problems || []).forEach(function(pb) { w[pb.type] = (w[pb.type] || 0) + 1; }); });
  var top = Object.keys(comps).sort(function(a, b) { return comps[b] - comps[a]; }).slice(0, 30).map(function(k) {
    var i = k.indexOf("|"); return { k: k.slice(0, i), c: k.slice(i + 1), n: comps[k] };
  });
  var fk = currentFileKey(), frames = [], byFrame = {}, used = {};
  invalid.forEach(function(it) { if (!it.frameId) { return; } var o = byFrame[it.frameId] || (byFrame[it.frameId] = {}), c = code[it.reason] || it.reason; o[c] = (o[c] || 0) + 1; });
  valid.forEach(function(it) { if (it.resolved) { return; } var nm = it.dsName || it.componentName || ""; if (nm) { used[nm] = (used[nm] || 0) + 1; } });
  (frameStates || []).forEach(function(f) {
    if (f.state === "verified") { ver++; } else if (f.state === "empty") { empty++; } else { fail++; }
    if (frames.length < 50) { frames.push({ h: tmHash(fk + ":" + f.id), st: f.state, n: f.instances, i: f.issues, r: byFrame[f.id] || {} }); }
  });
  var usedTop = Object.keys(used).sort(function(a, b) { return used[b] - used[a]; }).slice(0, 30).map(function(k) { return { c: k, n: used[k] }; });
  var total = valid.length + invalid.length;
  track("audit", {
    ms: Date.now() - t0, nf: (frameStates || []).length, n: total, ok: valid.length - acc - rule, acc: acc, rule: rule, iss: invalid.length,
    score: total ? Math.round(100 * valid.length / total) : null, r: r, mod: mod, w: w, ver: ver, fail: fail, empty: empty,
    nw: noWrite, notes: (notes || []).map(function(x) { return x.code; }), comps: top, used: usedTop, fr: frames,
    ly: rawSeen, lr: rawHit, lyc: rawSeen >= RAW_COUNT_MAX || undefined,   // layers outside components checked / with a raw value (lyc: count capped)
  });
}

function loadNoWrite() {   // after setReviewers(): admins are known only then
  figma.clientStorage.getAsync(NO_WRITE_KEY).then(function(v) { setNoWrite(!!v, false); }).catch(function() {});
}

function writeVerification(frame, info) {
  return computeFingerprint(frame).then(function(fp) {
    var who = null;
    try { who = figma.currentUser ? figma.currentUser.name : null; } catch(e) {}
    var rec = {
      v             : 1,
      fpv           : FP_VERSION,
      fp            : fp,
      at            : new Date().toISOString(),
      by            : who,
      pluginVersion : VERSION.string,
      libs          : info.libs,
      instances     : info.instances,
      resolved      : info.resolved || 0,
    };
    if (!noWrite) { frame.setSharedPluginData(VERIFY_NS, VERIFY_KEY, JSON.stringify(rec)); }
    return rec;
  });
}

function clearVerification(frame) {
  if (noWrite) { return; }
  try { frame.setSharedPluginData(VERIFY_NS, VERIFY_KEY, ""); } catch(e) {}
}

function finalizeVerification(frames, instanceCounts, issueCounts, libKeys, resolvedCounts) {
  var out = [];
  var i = 0;
  function next() {
    if (i >= frames.length) { return Promise.resolve(out); }
    var frame  = frames[i];
    var count  = instanceCounts[i];
    var issues = issueCounts[i];
    var resolvedN = resolvedCounts ? (resolvedCounts[i] || 0) : 0;
    i++;
    if (issues === 0 && count > 0) {
      return writeVerification(frame, { libs: libKeys, instances: count, resolved: resolvedN }).then(function(rec) {
        out.push({ id: frame.id, name: frame.name, state: "verified", instances: count, issues: 0, record: rec });
        return logAudit(frame, "verified", 0, count, resolvedN, rec.fp).then(next);
      }, function(err) {
        out.push({ id: frame.id, name: frame.name, state: "error", instances: count, issues: 0, error: err.message });
        return next();
      });
    }
    clearVerification(frame);
    var st = count === 0 ? "empty" : "failed";
    out.push({ id: frame.id, name: frame.name, state: st, instances: count, issues: issues });
    return computeFingerprint(frame).then(function(fp) {
      return logAudit(frame, st, issues, count, resolvedN, fp);
    }, function() { return null; }).then(next);
  }
  return next();
}

function readDevStatus(node) {
  try { return node.devStatus ? node.devStatus.type : null; } catch(e) { return null; }
}

function canSetDevStatus(node) {
  if (isDevMode() || !node.parent) { return false; }
  if (node.parent.type !== "PAGE" && node.parent.type !== "SECTION") { return false; }
  var p = node.parent;
  while (p && p.type !== "PAGE") {
    if (readDevStatus(p)) { return false; }
    p = p.parent;
  }
  return true;
}

function getVerificationState(frame) {
  var base = { id: frame.id, name: frame.name, devStatus: readDevStatus(frame) };
  var rec = readVerification(frame);
  var log = readLog(frame);
  var withLog = function(fp) {
    // A logged frame whose fingerprint moved since the last entry changed without anyone logging it.
    if (fp && log.length) { detectChange(frame, log, fp); retryAttribution(frame, readLog(frame)); }
    base.log = readLog(frame);
    return base;
  };
  if (!rec) {
    base.state = "none";
    base.canMarkReady = false;
    if (!log.length) { base.log = []; return Promise.resolve(base); }
    return computeFingerprint(frame).then(withLog);
  }
  if (rec.fpv !== FP_VERSION) {
    base.record = rec;
    base.state = "outdated";
    base.canMarkReady = false;
    base.log = log;
    return Promise.resolve(base);
  }
  return computeFingerprint(frame).then(function(fp) {
    base.record = rec;
    base.state = (fp === rec.fp) ? "verified" : "changed";
    base.canMarkReady = base.state === "verified" && canSetDevStatus(frame);
    return withLog(fp);
  });
}

// ── Frame log (2.10.0) ────────────────────────────────────────
// Every audited frame keeps a short history in shared plugin data, so everyone sees the same log:
//   { k: "a", at, by, uid, r: "verified"|"failed"|"empty", n: issues, i: instances, res, fp }   audit
//   { k: "c", at, by, uid, src: "p"|"d", from, fp, ed: [names] }                                change
// src "p" = edited while the editor had Darooghe open (exact name); "d" = detected later (no name;
// the team build adds the people who edited the file in that window, from Figma's version history).
var LOG_KEY          = "log";
var LOG_MAX          = 50;
var LOG_MERGE_MS     = 30 * 60 * 1000;   // consecutive changes by the same person merge into one entry
var REMOTE_QUIET_MS  = 8000;             // give a remote editor's own plugin time to log their change

function readLog(node) {
  try {
    var raw = node.getSharedPluginData(VERIFY_NS, LOG_KEY);
    var arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr : [];
  } catch(e) { return []; }
}

function writeLog(node, log) {
  if (isDevMode() || noWrite) { return; }
  try {
    if (log.length > LOG_MAX) { log = log.slice(log.length - LOG_MAX); }
    node.setSharedPluginData(VERIFY_NS, LOG_KEY, JSON.stringify(log));
  } catch(e) {}
}

function me() {
  try {
    var u = figma.currentUser;
    return u ? { name: u.name || null, id: u.id || null } : { name: null, id: null };
  } catch(e) { return { name: null, id: null }; }
}

// What changed: a small snapshot of the frame's instances (component, variant, override values) is kept
// next to the log ("snap"); a change entry stores the diff against it (d: [...], max SNAP_DIFF_MAX).
var SNAP_KEY       = "snap";
var SNAP_MAX_INST  = 400;
var SNAP_DIFF_MAX  = 12;

function readSnap(node) {
  try { var raw = node.getSharedPluginData(VERIFY_NS, SNAP_KEY); return raw ? JSON.parse(raw) : null; } catch(e) { return null; }
}
function writeSnap(node, snap) {
  if (isDevMode() || noWrite || !snap) { return; }
  try { node.setSharedPluginData(VERIFY_NS, SNAP_KEY, JSON.stringify(snap)); } catch(e) {}
}

// { v, inst: { id: [layerName, component, variant, key, { "layer · field": value }] }, cut }
function snapshotFrame(frame) {
  var list = [];
  try { collectInstances(frame, list); } catch(e) { list = []; }
  var cut = list.length > SNAP_MAX_INST;
  if (cut) { list = list.slice(0, SNAP_MAX_INST); }
  var inst = {};
  return Promise.all(list.map(function(n) {
    return getMain(n).then(function(main) {
      var names = componentNames(main);
      var ovs = {};
      var o = detectOverrides(n);
      for (var i = 0; i < o.length; i++) {
        if (SIG_SKIP_FIELDS[o[i].field]) { continue; }
        ovs[o[i].node + " · " + o[i].field] = o[i].value || "";
      }
      inst[n.id] = [n.name, names.name, names.variant, main ? main.key : null, ovs];
    }, function() { inst[n.id] = [n.name, null, null, null, {}]; });
  })).then(function() { return { v: 1, inst: inst, cut: cut }; });
}

// Differences between two snapshots, readable: added/removed instances, swaps/variant changes, override values.
function diffSnap(a, b) {
  var out = [];
  if (!a || !b) { return out; }
  var A = a.inst || {}, B = b.inst || {}, id, k;
  for (id in B) {
    var nb = B[id], na = A[id];
    if (!na) { out.push({ t: "add", n: nb[0], c: nb[1] }); continue; }
    if (na[3] !== nb[3]) {
      if (na[1] === nb[1]) { out.push({ t: "var", n: nb[0], c: nb[1], from: na[2], to: nb[2] }); }
      else { out.push({ t: "swap", n: nb[0], from: na[1], to: nb[1] }); }
    }
    var oa = na[4] || {}, ob = nb[4] || {};
    for (k in ob) { if (oa[k] !== ob[k]) { out.push({ t: "ov", n: nb[0], f: k, from: k in oa ? oa[k] : null, to: ob[k] }); } }
    for (k in oa) { if (!(k in ob)) { out.push({ t: "reset", n: nb[0], f: k, from: oa[k] }); } }
  }
  for (id in A) { if (!B[id]) { out.push({ t: "rm", n: A[id][0], c: A[id][1] }); } }
  return out;
}

function packDiff(d) {
  if (!d.length) { return [{ t: "other" }]; }      // fingerprint moved outside instances (loose layers, styles…)
  if (d.length <= SNAP_DIFF_MAX) { return d; }
  var keep = d.slice(0, SNAP_DIFF_MAX);
  keep.push({ t: "more", c: d.length - SNAP_DIFF_MAX });
  return keep;
}

// Snapshot now, diff against the stored one, store the new one. Resolves with the packed diff.
function snapAndDiff(frame) {
  var prev = readSnap(frame);
  return snapshotFrame(frame).then(function(cur) {
    writeSnap(frame, cur);
    return prev ? packDiff(diffSnap(prev, cur)) : null;
  }, function() { return null; });
}

function mergeDiff(oldD, newD) {
  if (!newD) { return oldD || null; }
  if (!oldD) { return newD; }
  var all = oldD.filter(function(x) { return x.t !== "other" && x.t !== "more"; })
                .concat(newD.filter(function(x) { return x.t !== "other" && x.t !== "more"; }));
  // Same layer + property edited twice → one line from the first value to the last.
  var out = [], seen = {};
  for (var i = 0; i < all.length; i++) {
    var x = all[i], key = (x.t === "ov" || x.t === "reset") ? "o|" + x.n + "|" + x.f : null;
    if (key && seen[key] !== undefined) {
      var y = out[seen[key]];
      y.t = x.t === "reset" ? (y.from === null ? "noop" : "reset") : "ov";
      y.to = x.to;
      if (y.t === "ov" && y.from === y.to) { y.t = "noop"; }
      continue;
    }
    if (key) { seen[key] = out.length; }
    out.push(x);
  }
  out = out.filter(function(x) { return x.t !== "noop"; });
  return out.length ? packDiff(out) : oldD;
}

function lastFp(log) {
  for (var i = log.length - 1; i >= 0; i--) { if (log[i] && log[i].fp) { return log[i].fp; } }
  return null;
}

// Adds a change entry, or extends the previous one when the same person (or "unknown") keeps editing.
function appendChange(node, entry) {
  var log = readLog(node);
  var last = log.length ? log[log.length - 1] : null;
  if (last && last.k === "c" && last.src === entry.src && (last.uid || null) === (entry.uid || null) && (last.by || null) === (entry.by || null) &&
      Date.parse(entry.at) - Date.parse(last.at) < LOG_MERGE_MS) {
    last.at = entry.at; last.fp = entry.fp;
    last.d = mergeDiff(last.d, entry.d);
  } else {
    log.push(entry);
    var hcKey = node.id + "|" + (entry.fp || entry.at);
    if (!noWrite && !tmHcSeen[hcKey] && readDevStatus(node) === "READY_FOR_DEV") {   // changed after handoff: rework once development started
      tmHcSeen[hcKey] = true;
      var rec = readVerification(node), kinds = [];
      (entry.d || []).forEach(function(x) { if (x && x.t && kinds.indexOf(x.t) < 0) { kinds.push(x.t); } });
      // fp: the same change seen by several people (or Dev Mode viewers) counts once in the analysis
      track("handoff_change", { fh: tmFrame(node), fp: entry.fp ? String(entry.fp).slice(0, 12) : null, src: entry.src || null, d: kinds, hv: rec && rec.at ? Math.round((Date.parse(entry.at) - Date.parse(rec.at)) / 36e5) : null });
    }
  }
  writeLog(node, log);
  return entry;
}

function logAudit(frame, result, issues, instances, resolved, fp) {
  if (isDevMode()) { return Promise.resolve(); }
  var log = readLog(frame);
  var prev = lastFp(log);
  var now = new Date().toISOString();
  var changed = prev && fp && prev !== fp && !(log.length && log[log.length - 1].k === "c" && log[log.length - 1].fp === fp);
  return snapAndDiff(frame).then(function(d) {
    return changed ? recordDetectedChange(frame, log, fp, now, d) : null;
  }).then(function() {
    var who = me();
    var l2 = readLog(frame);
    l2.push({ k: "a", at: now, by: who.name, uid: who.id, r: result, n: issues || 0, i: instances || 0, res: resolved || 0, fp: fp || null });
    writeLog(frame, l2);
  });
}

function lastEntryTime(log) {
  return log.length ? log[log.length - 1].at : null;
}

// Other people in the file right now (needs the "activeusers" permission); [] when unknown.
function otherActiveUsers() {
  var out = [];
  try {
    var meId = figma.currentUser ? figma.currentUser.id : null;
    var list = figma.activeUsers || [];
    for (var i = 0; i < list.length; i++) {
      if (list[i] && list[i].id !== meId && list[i].name && out.indexOf(list[i].name) < 0) { out.push(list[i].name); }
    }
  } catch(e) {}
  return out;
}

function recordDetectedChange(frame, log, fp, now, d) {
  var from = lastEntryTime(log);
  // A remote change: if exactly one other person was in the file it was them; with several, keep the candidates.
  var rw = remoteWho[frame.id], by = null, cand = null, maybe = null;
  if (rw && Date.now() - rw.at < 10 * 60 * 1000 && rw.names.length) {
    if (rw.names.length === 1) { by = rw.names[0]; } else { cand = rw.names.slice(0, 6); }
    delete remoteWho[frame.id];
  }
  // Not seen happening (the plugin was closed): the people in the file now are the likely editors.
  if (!by && !cand) { var here = otherActiveUsers(); if (here.length) { maybe = here.slice(0, 6); } }
  appendChange(frame, { k: "c", at: now || new Date().toISOString(), by: by, uid: null, src: by ? "r" : "d", cand: cand, maybe: maybe, from: from, fp: fp, d: d || null });
  return by ? Promise.resolve() : attributeFromVersions(frame);
}

// Who made an unattributed change, from Figma's version history (team build). Figma saves a version some time
// after the edit, so this runs again on later checks (ATTR_RETRY_MS) until a version names someone or ATTR_GIVE_UP_MS.
var ATTR_RETRY_MS   = 2 * 60 * 1000;
var ATTR_GIVE_UP_MS = 48 * 60 * 60 * 1000;
var attributing = {};
function unattributed(log) {
  for (var i = log.length - 1; i >= 0; i--) {
    var e = log[i];
    if (e.k !== "c") { continue; }
    if (e.src === "d" && !e.by && !(e.ed && e.ed.length) && Date.now() - Date.parse(e.at) < ATTR_GIVE_UP_MS) { return { e: e, i: i }; }
    return null;                                       // only the latest change is still worth resolving
  }
  return null;
}
function attributeFromVersions(frame) {
  if (isDevMode() || attributing[frame.id]) { return Promise.resolve(); }
  var hit = unattributed(readLog(frame));
  if (!hit) { return Promise.resolve(); }
  attributing[frame.id] = true;
  var at = hit.e.at, fp = hit.e.fp;
  return fileEditorsBetween(hit.e.from, at).then(function(res) {
    var l = readLog(frame);
    for (var i = l.length - 1; i >= 0; i--) {
      var e = l[i];
      if (e.k !== "c" || e.at !== at || e.fp !== fp) { continue; }
      e.vt = Date.now();
      if (res.names.length === 1) { e.by = res.names[0]; e.src = "v"; delete e.why; }      // only one person edited the file then
      else if (res.names.length) { e.ed = res.names.slice(0, 8); delete e.why; }
      else { e.why = res.why; }
      writeLog(frame, l);
      break;
    }
  }).then(function() { delete attributing[frame.id]; }, function() { delete attributing[frame.id]; });
}
function retryAttribution(frame, log) {
  var hit = unattributed(log);
  if (!hit || isDevMode()) { return; }
  if (hit.e.why === "no_key" || hit.e.why === "public") { return; }
  if (hit.e.vt && Date.now() - hit.e.vt < ATTR_RETRY_MS) { return; }
  attributeFromVersions(frame);
}

// Change noticed while checking the selection (someone edited without Darooghe open).
function detectChange(frame, log, fp) {
  if (isDevMode() || lastFp(log) === fp) { return; }
  // Our own edit: trackLocalChanges logs it by name. It's still ours while that is running (localPending)
  // and for a short while after the last local change (the verify check runs before the local tracker).
  if (localDirty[frame.id] || localPending[frame.id]) { return; }
  if (lastLocalAt[frame.id] && Date.now() - lastLocalAt[frame.id] < LOCAL_GRACE_MS) { scheduleVerifyCheck(LOCAL_GRACE_MS); return; }
  var r = remoteDirty[frame.id];
  if (r && Date.now() - r < REMOTE_QUIET_MS) { scheduleVerifyCheck(REMOTE_QUIET_MS); return; }
  if (detecting[frame.id]) { return; }
  detecting[frame.id] = true;
  snapAndDiff(frame).then(function(d) {
    if (lastFp(readLog(frame)) !== fp) { return recordDetectedChange(frame, readLog(frame), fp, null, d); }
  }).then(function() { delete detecting[frame.id]; }, function() { delete detecting[frame.id]; });
}

// Edits made here while the plugin is open: logged with the current user's name.
var LOCAL_GRACE_MS = 15000;
var localPending = {};    // frame id → the local tracker is logging it right now
var lastLocalAt  = {};    // frame id → time of our last edit to it
var remoteWho    = {};    // frame id → { at, names } — who else was in the file when a remote change arrived
var localDirty   = {};
var detecting    = {};
var remoteDirty  = {};
var trackTimer   = null;

function topFrameOf(node) {
  var cur = node, top = null;
  while (cur && cur.type !== "PAGE" && cur.type !== "DOCUMENT") {
    if (cur.parent && (cur.parent.type === "PAGE" || cur.parent.type === "SECTION") && isAuditTarget(cur)) { top = cur; }
    cur = cur.parent;
  }
  return top;
}

var META_PROPS = { pluginData: true, sharedPluginData: true, relaunchData: true, devStatus: true };
function onlyMeta(props) {
  for (var i = 0; i < props.length; i++) { if (!META_PROPS[props[i]]) { return false; } }
  return true;
}

// Frames shown in the last audit result: the first real edit to one of them makes that result stale.
var auditedFrames = {};

function onNodeChanges(event) {
  if (isDevMode() || !event || !event.nodeChanges) { return; }
  var changes = event.nodeChanges;
  var stale = [];
  for (var i = 0; i < changes.length && i < 200; i++) {
    var c = changes[i];
    if (c.type === "PROPERTY_CHANGE" && c.properties && onlyMeta(c.properties)) { continue; }
    var n = c.node;
    if (!n || n.removed) { continue; }
    var top = null;
    try { top = topFrameOf(n); } catch(e) { top = null; }
    if (!top) { continue; }
    if (auditedFrames[top.id]) { delete auditedFrames[top.id]; stale.push(top.id); }
    if (c.origin === "REMOTE") { remoteDirty[top.id] = Date.now(); remoteWho[top.id] = { at: Date.now(), names: otherActiveUsers() }; }
    else { localDirty[top.id] = true; lastLocalAt[top.id] = Date.now(); }
  }
  if (stale.length) { send("RESULT_STALE", { frameIds: stale }); }
  if (trackTimer) { clearTimeout(trackTimer); }
  trackTimer = setTimeout(trackLocalChanges, 1500);
}

function trackLocalChanges() {
  trackTimer = null;
  var ids = Object.keys(localDirty);
  localDirty = {};
  ids.forEach(function(id) {
    localPending[id] = true;
    getNodeSafely(id).then(function(frame) {
      if (!frame || frame.removed) { return; }
      var log = readLog(frame);
      if (!log.length) { return; }                       // only frames that were audited at least once
      return computeFingerprint(frame).then(function(fp) {
        if (fp === lastFp(log)) { return; }
        return snapAndDiff(frame).then(function(d) {
          var who = me();
          appendChange(frame, { k: "c", at: new Date().toISOString(), by: who.name, uid: who.id, src: "p", fp: fp, d: d });
          scheduleVerifyCheck(0);
        });
      });
    }).then(function() { delete localPending[id]; }, function() { delete localPending[id]; });
  });
}

// Version history (team build): who saved versions of this file between two moments.
// File level, not frame level — shown as "people who edited the file in this window".
function fileEditorsBetween() { return Promise.resolve({ names: [], why: "public" }); }

function verifyTargetsFromSelection() {
  var sel = figma.currentPage.selection;
  if (!sel || !sel.length) { return []; }
  var node = sel[0];

  if (node.type === "SECTION") { return expandTargets([node]); }

  // Nearest ancestor (or self) carrying a record wins; otherwise the top-level frame.
  var cur = node, top = null;
  while (cur && cur.type !== "PAGE") {
    if (readVerification(cur)) { return [cur]; }
    if (cur.parent && (cur.parent.type === "PAGE" || cur.parent.type === "SECTION")) {
      top = isAuditTarget(cur) ? cur : null;
      break;
    }
    cur = cur.parent;
  }
  return top ? [top] : [];
}

var verifySeq   = 0;
var verifyTimer = null;

function scheduleVerifyCheck(delay) {
  if (verifyTimer) { clearTimeout(verifyTimer); }
  verifyTimer = setTimeout(function() {
    verifyTimer = null;
    sendVerificationStatus();
  }, delay || 0);
}

function sendVerificationStatus() {
  var seq = ++verifySeq;
  var targets;
  try { targets = verifyTargetsFromSelection(); } catch(e) { targets = []; }
  if (!targets.length) { send("VERIFICATION_STATUS", { seq: seq, items: [] }); return; }
  var checks = [];
  for (var i = 0; i < targets.length; i++) { checks.push(getVerificationState(targets[i])); }
  Promise.all(checks).then(function(items) {
    send("VERIFICATION_STATUS", { seq: seq, items: items });
  }).catch(function(err) {
    send("VERIFICATION_STATUS", { seq: seq, items: [], error: err.message });
  });
}

var listenedPage = null;
function onPageNodeChange(event) { onNodeChanges(event); scheduleVerifyCheck(600); }
function attachPageListener() {
  try { if (listenedPage) { listenedPage.off("nodechange", onPageNodeChange); } } catch(e) {}
  listenedPage = figma.currentPage;
  try { listenedPage.on("nodechange", onPageNodeChange); } catch(e) {}
}

function handleMarkReadyForDev(msg) {
  getNodeSafely(msg.frameId).then(function(node) {
    if (!node) { throw new Error("Frame not found."); }
    return getVerificationState(node).then(function(st) {
      if (st.state !== "verified") { throw new Error("This frame is not verified, or it changed since verification. Re-audit it first."); }
      if (!st.canMarkReady) { throw new Error("Only frames placed directly on a page or section can be marked ready for dev."); }
      node.devStatus = { type: "READY_FOR_DEV", description: "Verified by DAROOGHE v" + VERSION.string };
      track("ready", { fh: tmFrame(node) });
      send("READY_FOR_DEV_RESULT", { success: true, frameName: node.name });
      scheduleVerifyCheck(0);
    });
  }).catch(function(err) {
    send("READY_FOR_DEV_RESULT", { success: false, error: err.message });
  });
}

// ── Resolutions (approved exceptions) ─────────────────────────
// A DS reviewer can approve an issue on an instance. The approval is stored on the
// instance (shared plugin data) with a signature of the issue at that moment; if the
// instance changes afterwards the approval expires and the issue comes back.

var RESOLVE_KEY = "resolution";
var RESOLVABLE  = { ds_overridden: true, unpublished: true, external_library: true, local_component: true, outdated: true, detached: true, missing_main: true };   // every issue type
var cachedReviewers = [];

// guidelines.reviewers → can resolve issues.  guidelines.admins → manage the shared token
// and see the reviewer IDs. No "admins" list = reviewers act as admins (so nobody is locked out).
var cachedAdmins = [];
var reviewerNames = [];

function idList(list, names) {
  var out = [];
  for (var i = 0; i < (list || []).length; i++) {
    var r = list[i];
    var id = (r && typeof r === "object") ? r.id : r;
    if (id !== undefined && id !== null && id !== "") {
      out.push(String(id));
      if (names) { names.push((r && typeof r === "object" && r.name) ? String(r.name) : String(id)); }
    }
  }
  return out;
}

function setReviewers(guidelines) {
  reviewerNames   = [];
  cachedReviewers = idList(guidelines && Array.isArray(guidelines.reviewers) ? guidelines.reviewers : [], reviewerNames);
  cachedAdmins    = idList(guidelines && Array.isArray(guidelines.admins) ? guidelines.admins : [], null);
  var u = null;
  try { u = figma.currentUser; } catch(e) {}
  send("USER_INFO", {
    id                  : u ? u.id : null,
    name                : u ? u.name : null,
    isReviewer          : isReviewer(),
    isAdmin             : isAdmin(),
    edition             : EDITION,
    reviewers           : reviewerNames,
    reviewersConfigured : cachedReviewers.length > 0,
  });
}

function isAdmin() {
  if (EDITION === "public") { return true; }
  if (!cachedAdmins.length) { return isReviewer(); }
  var u = null;
  try { u = figma.currentUser; } catch(e) {}
  return !!(u && u.id) && cachedAdmins.indexOf(String(u.id)) > -1;
}

function isReviewer() {
  if (EDITION === "public") { return true; }   // public: anyone can accept an exception (their name is recorded)
  var u = null;
  try { u = figma.currentUser; } catch(e) {}
  if (!u || !u.id) { return false; }
  return cachedReviewers.indexOf(String(u.id)) > -1;
}

function readResolution(node) {
  try {
    var raw = node.getSharedPluginData(VERIFY_NS, RESOLVE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch(e) { return null; }
}

function publicResolution(rec) {
  if (!rec) { return null; }
  return { by: rec.by ? rec.by.name : null, at: rec.at, note: rec.note || "" };
}

// v2 (2.7.2): geometry ("Dimensions") is left out of the signature, like the verification
// fingerprint. With it, any reflow (a text edit nearby, a fill-container resize) made an
// accepted exception look "changed since". v1 records are still checked the old way.
var RESOLVE_SIG_VERSION = 3;
var SIG_SKIP_FIELDS = { "Dimensions": true };

function overridesSignature(overrides, legacy) {
  var parts = [];
  for (var i = 0; i < (overrides || []).length; i++) {
    var o = overrides[i];
    if (!legacy && SIG_SKIP_FIELDS[o.field]) { continue; }
    if (o.type === "swap") { continue; }   // nested swaps are checked separately (rec.swaps)
    parts.push(o.node + "|" + o.field + "|" + (o.sv !== undefined ? o.sv : o.value));
  }
  parts.sort();
  return parts.join(";");
}

function issueSignature(instance, reason, overrides, legacy) {
  return fpInstance(instance).then(function(txt) {
    return fpHash(reason + "\n" + txt + "\n" + overridesSignature(overrides, legacy));
  });
}

// Does a stored resolution still match the instance as it is now?
// v3 (2.10.0): the signature covers only what was accepted — the issue type, which component it is, and
// the override values by layer NAME. No internal layer IDs (they change when a frame is duplicated or
// pasted) and no layout-driven fields, so an exception holds until the accepted issue itself changes.
function sigReason(reason) { return (reason === "external_library" || reason === "outdated") ? "remote" : reason; }

function issueSignatureV3(instance, reason, overrides) {
  if (instance.type !== "INSTANCE") {
    // Detached frame: the component it was detached from identifies the accepted issue.
    var info = safeGet(instance, "detachedInfo") || {};
    return Promise.resolve(fpHash("v3\n" + sigReason(reason) + "\ndet:" + (info.componentKey || info.componentId || "none") + "\n"));
  }
  return getMain(instance).then(function(main) {
    return fpHash("v3\n" + sigReason(reason) + "\n" + (main ? main.key : "none") + "\n" + overridesSignature(overrides, false));
  });
}

function resolutionMatches(instance, rec, overrides) {
  if (rec.v >= 3) {
    return issueSignatureV3(instance, rec.reason, overrides).then(function(sig) { return sig === rec.sig; });
  }
  // v1/v2 records: check with the old signature; when they still match, upgrade them to v3 in place.
  var legacy = !(rec.v >= 2);
  return issueSignature(instance, rec.reason, overrides, legacy).then(function(sig) {
    if (sig !== rec.sig) { return false; }
    if (!isDevMode() && !noWrite) {
      issueSignatureV3(instance, rec.reason, overrides).then(function(s3) {
        rec.v = 3; rec.sig = s3;
        try { instance.setSharedPluginData(VERIFY_NS, RESOLVE_KEY, JSON.stringify(rec)); } catch(e) {}
      }, function() {});
    }
    return true;
  });
}

// Nested swaps to non-DS components need the DS list, so they come from the last audit, not detectOverrides().
var lastAuditOverrides = {};   // instance id → overrides of its issue in the last audit

function swapList(overrides) {
  var out = [];
  for (var i = 0; i < (overrides || []).length; i++) {
    if (overrides[i].type === "swap") { out.push(overrides[i].node + "|" + overrides[i].value); }
  }
  return out.sort();
}

// ── Team rules (approved patterns, from the guidelines gist) ──
// guidelines.rules: [{ reason, component, name, overrides?: ["Field@layer=value", …], note, by, at }]
// An issue matches when its type (EXT/OLD as one) and component (set key, or component key) are the rule's
// and every override it has is listed in the rule (no "overrides" = any). MIS has no component, so no rule.
var teamRules = [];
function setTeamRules(guidelines) {
  var list = guidelines && Array.isArray(guidelines.rules) ? guidelines.rules : [];
  teamRules = [];
  for (var i = 0; i < list.length; i++) {
    var r = list[i];
    if (!r || typeof r.reason !== "string" || typeof r.component !== "string" || !r.component) { continue; }
    teamRules.push({
      reason: r.reason, component: r.component, name: r.name ? String(r.name) : "",
      overrides: Array.isArray(r.overrides) ? r.overrides.map(String) : null,
      note: r.note ? String(r.note) : "", by: r.by ? String(r.by) : "", at: r.at ? String(r.at) : "",
    });
  }
  send("TEAM_RULES", { rules: teamRules });
}
function overrideStrings(overrides) {
  var out = [];
  for (var i = 0; i < (overrides || []).length; i++) { var o = overrides[i]; out.push(o.field + "@" + o.node + "=" + (o.value || "")); }
  return out;
}
function matchTeamRule(issue) {
  if (!teamRules.length || !issue || !issue.componentKey || issue.reason === "missing_main") { return null; }
  var ov = overrideStrings(issue.overrides);
  for (var i = 0; i < teamRules.length; i++) {
    var r = teamRules[i];
    if (sigReason(r.reason) !== sigReason(issue.reason) || r.component !== issue.componentKey) { continue; }
    if (r.overrides) {
      var all = true;
      for (var k = 0; k < ov.length; k++) { if (r.overrides.indexOf(ov[k]) < 0) { all = false; break; } }
      if (!all) { continue; }
    }
    return r;
  }
  return null;
}
function buildRuleItem(instance, issue, rule, sourceName) {
  var item = buildValidItem(instance, issue.componentName, sourceName);
  item.resolved      = { by: rule.by, at: rule.at, note: rule.note, rule: true };
  item.resolvedIssue = issue;
  return item;
}


// ── Escalation to the DS team (Mattermost) ──
// A designer sends issues to the DS team's channel when they need a decision. The incoming-webhook URL is in the
// team config (never in the code). The UI posts the message itself (no-cors: the webhook needn't allow CORS);
// after it went out, each instance is marked so the result shows "sent to the DS team".
var ESC_KEY = "escalation";
var escalationCfg = null;   // { url, channel }
function setEscalation(guidelines) {
  var m = guidelines && guidelines.mattermost, url = "";
  if (m) { url = m.webhook ? String(m.webhook) : (m.webhookB64 ? b64decode(m.webhookB64) : ""); }
  url = url.replace(/^\s+|\s+$/g, "");
  escalationCfg = /^https:\/\//.test(url) ? { url: url, channel: m.channel ? String(m.channel) : "" } : null;
  send("ESCALATION_INFO", { enabled: !!escalationCfg, channel: escalationCfg ? escalationCfg.channel : "" });
}
function readEscalation(node) {
  try { var raw = node.getSharedPluginData(VERIFY_NS, ESC_KEY); return raw ? JSON.parse(raw) : null; } catch(e) { return null; }
}
function handleEscalatePrepare(msg) {
  if (!escalationCfg) { send("ESCALATE_RESULT", { ok: false, code: "not_configured", req: msg.req }); return; }
  send("ESCALATE_SEND", { url: escalationCfg.url, req: msg.req });
}
function handleEscalateSent(msg) {
  var ids = msg.ids || [], who = me(), rec = JSON.stringify({ at: new Date().toISOString(), by: who.name, uid: who.id, note: String(msg.note || "").slice(0, 500) });
  Promise.all((noWrite ? [] : ids).map(function(id) {   // baseline mode: the message went out, the file stays untouched
    return getNodeSafely(id).then(function(n) { if (n) { try { n.setSharedPluginData(VERIFY_NS, ESC_KEY, rec); } catch(e) {} } }, function() {});
  })).then(function() {
    tmFramesOf(ids).then(function(fh) { track("esc", { n: ids.length, k: msg.kinds || null, note: !!msg.note, fh: fh }); });
    send("ESCALATE_RESULT", { ok: true, n: ids.length, req: msg.req, record: JSON.parse(rec) });
  });
}

function checkResolution(instance, issue) {
  var rec = readResolution(instance);
  if (!rec) { return Promise.resolve({ state: "none" }); }
  // Exceptions accepted as EXT before 2.10.1 still count when the same instance is now classified OLD.
  var sameIssue = sigReason(rec.reason) === sigReason(issue.reason);
  if (!RESOLVABLE[issue.reason] || !sameIssue) {
    return Promise.resolve({ state: "stale", record: rec });
  }
  return resolutionMatches(instance, rec, issue.overrides).then(function(ok) {
    // Non-DS nested swaps must be the same ones that were accepted.
    if (ok && swapList(issue.overrides).join(";") !== (rec.swaps || []).join(";")) { ok = false; }
    return { state: ok ? "resolved" : "stale", record: rec };
  }, function() {
    return { state: "none" };
  });
}

function buildResolvedItem(instance, issue, rec, sourceName) {
  var item = buildValidItem(instance, issue.componentName, sourceName);
  item.resolved      = publicResolution(rec);
  item.resolvedIssue = issue;
  return item;
}

// Records one exception. Resolves with the RESOLVE_RESULT payload (never rejects).
function resolveOne(msg) {
  if (isDevMode())  { return Promise.resolve({ success: false, nodeId: msg.nodeId, error: "Resolving isn't available in Dev Mode." }); }
  if (!isReviewer()) { return Promise.resolve({ success: false, nodeId: msg.nodeId, error: "Only design system reviewers can resolve issues." }); }
  if (!RESOLVABLE[msg.reason]) { return Promise.resolve({ success: false, nodeId: msg.nodeId, error: "This issue type can't be resolved." }); }

  return getNodeSafely(msg.nodeId).then(function(node) {
    var isDetached = !!node && node.type === "FRAME" && !!safeGet(node, "detachedInfo");
    if (!node || (node.type !== "INSTANCE" && !isDetached)) { throw new Error("Instance not found."); }
    var overrides = isDetached ? [] : detectOverrides(node);
    return issueSignatureV3(node, msg.reason, overrides).then(function(sig) {
      var u = figma.currentUser;
      var rec = {
        v      : RESOLVE_SIG_VERSION,
        reason : msg.reason,
        sig    : sig,
        swaps  : swapList(lastAuditOverrides[node.id] || []),
        note   : String(msg.note || "").slice(0, 500),
        by     : { id: u ? u.id : null, name: u ? u.name : null },
        at     : new Date().toISOString(),
      };
      node.setSharedPluginData(VERIFY_NS, RESOLVE_KEY, JSON.stringify(rec));
      return { success: true, nodeId: node.id, resolution: publicResolution(rec) };
    });
  }).catch(function(err) {
    return { success: false, nodeId: msg.nodeId, error: err.message };
  });
}

function handleResolveIssue(msg) {
  resolveOne(msg).then(function(res) {
    if (res.success) { tmFramesOf([msg.nodeId]).then(function(fh) { track("accept", { r: msg.reason || null, n: 1, note: !!msg.note, fh: fh }); }); }
    send("RESOLVE_RESULT", res);
  });
}

// Bulk: { items: [{ nodeId, reason }], note } — one after another, a RESOLVE_RESULT (bulk: true) per item,
// then RESOLVE_BULK_DONE with the counts.
function handleResolveIssues(msg) {
  var items = (msg.items || []).slice(0, 500);
  var ok = 0, failed = 0;
  var chain = Promise.resolve();
  items.forEach(function(it) {
    chain = chain.then(function() {
      return resolveOne({ nodeId: it.nodeId, reason: it.reason, note: msg.note }).then(function(res) {
        if (res.success) { ok++; } else { failed++; }
        res.bulk = true;
        send("RESOLVE_RESULT", res);
      });
    });
  });
  chain.then(function() {
    if (ok) { tmFramesOf(items.map(function(it) { return it.nodeId; })).then(function(fh) { track("accept", { r: null, n: ok, note: !!msg.note, bulk: true, fh: fh }); }); }
    send("RESOLVE_BULK_DONE", { ok: ok, failed: failed });
  });
}

function handleUnresolveIssue(msg) {
  if (isDevMode() || !isReviewer()) { send("UNRESOLVE_RESULT", { success: false, nodeId: msg.nodeId, error: "Only design system reviewers can undo a resolution." }); return; }
  getNodeSafely(msg.nodeId).then(function(node) {
    if (!node) { throw new Error("Instance not found."); }
    node.setSharedPluginData(VERIFY_NS, RESOLVE_KEY, "");
    // The issue is open again, so any frame verified with this approval is no longer verified.
    var p = node.parent;
    while (p && p.type !== "PAGE") {
      if (readVerification(p)) { clearVerification(p); }
      p = p.parent;
    }
    send("UNRESOLVE_RESULT", { success: true, nodeId: node.id });
    scheduleVerifyCheck(0);
  }).catch(function(err) {
    send("UNRESOLVE_RESULT", { success: false, nodeId: msg.nodeId, error: err.message });
  });
}

// ── Data Builders ─────────────────────────────────────────────

function buildValidItem(instance, dsName, sourceName) {
  return {
    id       : instance.id,
    name     : instance.name,
    dsName   : dsName,
    dsSource : sourceName,
    path     : getNodePath(instance),
    parent   : getDirectParent(instance),
  };
}

// ── Resolution report (admins) ──────────────────────────────
// Scans every page of the open file for instances carrying a resolution and reports
// each one with its current state: "active" (still matches) or "stale" (changed since).
function topFrameName(node) {
  var cur = node, top = null;
  while (cur && cur.parent && cur.type !== "PAGE") {
    if (cur.parent.type === "PAGE" || cur.parent.type === "SECTION") { top = cur; break; }
    cur = cur.parent;
  }
  return top ? top.name : "";
}

function handleExportResolutions() {
  if (!isAdmin()) { send("RESOLUTIONS_REPORT", { success: false, error: "admin_only" }); return; }
  var loadAll = (figma.loadAllPagesAsync ? figma.loadAllPagesAsync() : Promise.resolve());
  loadAll.then(function() {
    var found = [];
    var pages = figma.root.children;
    for (var p = 0; p < pages.length; p++) {
      var list = [];
      try { list = pages[p].findAllWithCriteria({ types: ["INSTANCE", "FRAME"] }); } catch(e) { list = []; }
      for (var i = 0; i < list.length; i++) {
        var rec = readResolution(list[i]);
        if (rec) { found.push({ node: list[i], rec: rec, page: pages[p].name }); }
      }
    }
    var rows = [];
    var chain = Promise.resolve();
    found.forEach(function(f) {
      chain = chain.then(function() {
        return getMain(f.node).then(function(main) {
          var names = componentNames(main);
          return resolutionMatches(f.node, f.rec, detectOverrides(f.node)).then(function(ok) { return ok; }, function() { return false; })
            .then(function(active) {
              rows.push({
                page      : f.page,
                frame     : topFrameName(f.node),
                layer     : f.node.name,
                nodeId    : f.node.id,
                component : names.name || "",
                variant   : names.variant || "",
                reason    : f.rec.reason || "",
                by        : f.rec.by ? (f.rec.by.name || "") : "",
                at        : f.rec.at || "",
                note      : f.rec.note || "",
                status    : active ? "active" : "stale",
              });
            });
        });
      });
    });
    return chain.then(function() {
      var fileKey = null;
      try { fileKey = figma.fileKey || null; } catch(e) {}
      send("RESOLUTIONS_REPORT", { success: true, fileName: figma.root.name, fileKey: fileKey, rows: rows });
    });
  }).catch(function(err) {
    send("RESOLUTIONS_REPORT", { success: false, error: err.message });
  });
}

function componentNames(mainComp) {
  // Variants: readable name is the component set ("Button/Primary"), plus the variant ("State=Pressed").
  if (!mainComp) { return { name: null, variant: null }; }
  try {
    if (mainComp.parent && mainComp.parent.type === "COMPONENT_SET") {
      return { name: mainComp.parent.name, variant: mainComp.name };
    }
  } catch(e) {}
  return { name: mainComp.name, variant: null };
}

// ── Remote component lookup (2.10.1) ─────────────────────────
// GET /v1/components/:key → which file publishes it. 404 = no longer published (an old or deleted
// version the instance still points to). Cached per key and per file for the session.
function lookupRemoteComponent() { return Promise.resolve({ state: "unknown" }); }

function buildDetachedItem(frame, dsNames, dsSets) {
  var info = safeGet(frame, "detachedInfo") || {};
  var key  = info.componentKey;
  var compName = key && dsNames[key] ? dsNames[key] : null;
  var setName  = key && dsSets[key] ? dsSets[key] : null;
  return {
    id                : frame.id,
    name              : frame.name,
    reason            : "detached",
    overrides         : [],
    componentKey      : key || null,
    mainComponentName : compName,
    componentName     : setName || compName,
    variantName       : setName ? compName : null,
    inDS              : !!compName,
    path              : getNodePath(frame),
    parent            : getDirectParent(frame),
  };
}

function buildInvalidItem(instance, reason, mainComp, overrides) {
  var names = componentNames(mainComp);
  var setKey = null;
  try { setKey = mainComp && mainComp.parent && mainComp.parent.type === "COMPONENT_SET" ? mainComp.parent.key : null; } catch(e) { setKey = null; }
  return {
    componentKey      : setKey || (mainComp ? mainComp.key : null),   // component set (or component): what team rules name
    id                : instance.id,
    name              : instance.name,
    reason            : reason,
    overrides         : overrides,
    mainComponentName : mainComp ? mainComp.name : null,
    componentName     : names.name,
    variantName       : names.variant,
    path              : getNodePath(instance),
    parent            : getDirectParent(instance),
  };
}

// ── Helpers ───────────────────────────────────────────────────

// Visible instances (not their insides). With `detached`, also collects frames that were detached
// from a library component (Figma's detachedInfo) — their contents are still scanned.
function collectInstances(node, result, detached) {
  if (node.visible === false) { return; }
  if (node.type === "INSTANCE") { result.push(node); return; }
  if (detached && node.type === "FRAME") {
    var info = safeGet(node, "detachedInfo");
    if (info && info.type === "library") { detached.push(node); }
  }
  if (node.children) {
    for (var i = 0; i < node.children.length; i++) {
      collectInstances(node.children[i], result, detached);
    }
  }
}

function getNodePath(node) {
  var parts  = [];
  var cursor = node.parent;
  while (cursor && cursor.type !== "PAGE") {
    parts.unshift(cursor.name);
    cursor = cursor.parent;
  }
  return parts.join(" > ");
}

function getDirectParent(node) {
  var p = node.parent;
  if (!p || p.type === "PAGE") { return null; }
  return { id: p.id, name: p.name, type: p.type };
}

function currentFileKey() {
  try { return figma.fileKey || null; } catch(e) { return null; }
}

// ── Messaging ─────────────────────────────────────────────────

function send(type, payload) {
  var msg  = payload || {};
  msg.type = type;
  figma.ui.postMessage(msg);
}

// code + params let the UI show the message in its language; text is the English fallback.
function sendStatus(text, code, params) {
  var m = { text: text };
  if (code) { m.code = code; for (var k in (params || {})) { m[k] = params[k]; } }
  send("STATUS", m);
}
function sendError(text)  { send("ERROR",  { text: text }); }
